-- GENERATED by `npm run sql:bundle`. Paste into Supabase > SQL Editor > Run.

-- ===== 0001_init.sql =====
-- FunnyBloxy's Academic Comeback: core schema
-- Run in the Supabase SQL editor (or `supabase db push`).
-- Security model:
--   * Every table has row level security (RLS) on.
--   * Students read only what they are allowed to see and change data ONLY through
--     SECURITY DEFINER functions (submit_quiz, battle functions...) so XP, scores and
--     answers can never be forged from the browser.
--   * Tutor actions run on the server (Next.js server actions) after a role check.

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------- enums
do $$ begin
  create type user_role as enum ('student','tutor');
  create type account_status as enum ('pending','approved','suspended');
  create type tier as enum ('O','AS','A');
  create type pub_status as enum ('draft','locked','scheduled','published');
  create type resource_section as enum ('library','class');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------- profiles
create table if not exists profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  discord_id text,
  discord_username text,
  display_name text not null default 'New player',
  discord_avatar_url text,
  role user_role not null default 'student',
  status account_status not null default 'pending',
  tier tier not null default 'O',
  contact text,
  parent_name text,
  parent_contact text,
  roblox_username text,
  roblox_user_id bigint,
  roblox_headshot_url text,
  avatar_mode text not null default 'discord' check (avatar_mode in ('discord','roblox','blocky','both')),
  blocky jsonb not null default '{}'::jsonb,
  title text,
  theme text not null default 'bloxy' check (theme in ('bloxy','gamer','retro')),
  xp integer not null default 0,
  coins integer not null default 0,
  streak integer not null default 0,
  best_streak integer not null default 0,
  last_study_date date,
  announced_level integer not null default 1,
  last_seen_at timestamptz,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------- helpers
create or replace function is_tutor() returns boolean
language sql stable security definer set search_path = public as $$
  select exists(select 1 from profiles where id = auth.uid() and role = 'tutor' and status = 'approved');
$$;

create or replace function is_approved() returns boolean
language sql stable security definer set search_path = public as $$
  select exists(select 1 from profiles where id = auth.uid() and status = 'approved');
$$;

create or replace function tier_rank(t tier) returns int language sql immutable as $$
  select case t when 'O' then 0 when 'AS' then 1 else 2 end;
$$;

-- total XP needed to reach level L: 50 * L * (L-1)  (L1 = 0, L2 = 100, L3 = 300, L5 = 1000, L10 = 4500)
create or replace function level_from_xp(x int) returns int language sql immutable as $$
  select greatest(1, floor((1 + sqrt(1 + 4 * x / 50.0)) / 2)::int);
$$;

-- ---------------------------------------------------------------- courses & content
create table if not exists courses (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  code text not null,
  title text not null,
  tier tier not null,
  exam_label text,
  description text,
  color text not null default '#22c55e',
  icon text not null default 'book',
  sort int not null default 0,
  active boolean not null default true
);

create table if not exists chapters (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references courses(id) on delete cascade,
  number text not null,
  title text not null,
  summary text,
  sort int not null default 0,
  status pub_status not null default 'published',
  release_at timestamptz
);
create index if not exists chapters_course on chapters(course_id, sort);

create table if not exists parts (
  id uuid primary key default gen_random_uuid(),
  chapter_id uuid not null references chapters(id) on delete cascade,
  number text not null,
  title text not null,
  body text,
  video_url text,
  sort int not null default 0,
  status pub_status not null default 'published',
  release_at timestamptz
);
create index if not exists parts_chapter on parts(chapter_id, sort);

-- files and links: "library" (ready-made) or "class" (tutor's lecture notes)
create table if not exists resources (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references courses(id) on delete cascade,
  chapter_id uuid references chapters(id) on delete cascade,
  part_id uuid references parts(id) on delete cascade,
  section resource_section not null default 'class',
  title text not null,
  kind text not null default 'pdf' check (kind in ('pdf','video','worksheet','link','image','other')),
  file_path text,
  url text,
  status pub_status not null default 'published',
  release_at timestamptz,
  created_at timestamptz not null default now()
);

-- visible to students = published, or scheduled and the release time has passed
create or replace function is_live(s pub_status, rel timestamptz) returns boolean language sql stable as $$
  select s = 'published' or (s = 'scheduled' and rel is not null and rel <= now());
$$;

-- ---------------------------------------------------------------- quizzes
create table if not exists quizzes (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references courses(id) on delete cascade,
  chapter_id uuid references chapters(id) on delete cascade,
  title text not null,
  kind text not null default 'quiz' check (kind in ('quiz','speedrun')),
  xp_reward int not null default 50,
  time_limit_sec int,
  status pub_status not null default 'published',
  release_at timestamptz,
  sort int not null default 0
);

create table if not exists questions (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references courses(id) on delete cascade,
  chapter_id uuid references chapters(id) on delete cascade,
  quiz_id uuid references quizzes(id) on delete cascade,
  prompt text not null,
  options jsonb not null,          -- ["A","B","C","D"]
  explanation text,
  difficulty int not null default 1,
  battle_ok boolean not null default true
);
create index if not exists questions_quiz on questions(quiz_id);
create index if not exists questions_course on questions(course_id);

-- answers live in their own table that students can never read
create table if not exists question_keys (
  question_id uuid primary key references questions(id) on delete cascade,
  correct int not null
);

create table if not exists quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles(id) on delete cascade,
  quiz_id uuid not null references quizzes(id) on delete cascade,
  question_ids uuid[] not null,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  score int,
  total int,
  time_ms int,
  points int,
  xp_awarded int not null default 0,
  flagged boolean not null default false,
  answers jsonb
);
create index if not exists attempts_user on quiz_attempts(user_id, quiz_id);

-- ---------------------------------------------------------------- XP, achievements, challenges
create table if not exists xp_events (
  id bigserial primary key,
  user_id uuid not null references profiles(id) on delete cascade,
  amount int not null,
  coins int not null default 0,
  multiplier numeric(4,2) not null default 1,
  reason text not null,
  ref text,
  created_at timestamptz not null default now()
);
create index if not exists xp_user on xp_events(user_id, created_at desc);

create table if not exists achievements (
  id uuid primary key default gen_random_uuid(),
  code text unique not null,
  title text not null,
  description text not null,
  icon text not null default 'trophy',
  rarity text not null default 'common' check (rarity in ('common','rare','epic','legendary')),
  xp_reward int not null default 50,
  criteria jsonb not null,          -- {"type":"streak","value":7}
  active boolean not null default true
);

create table if not exists user_achievements (
  user_id uuid references profiles(id) on delete cascade,
  achievement_id uuid references achievements(id) on delete cascade,
  earned_at timestamptz not null default now(),
  primary key (user_id, achievement_id)
);

-- recurring challenges: progress is tracked per period (day or ISO week)
create table if not exists challenges (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  period text not null check (period in ('daily','weekly','once')),
  type text not null check (type in ('quiz_pass','quiz_specific','study_days','homework_on_time','attendance','battle_win','battle_play','xp_earned')),
  target int not null default 1,
  quiz_id uuid references quizzes(id) on delete set null,
  xp_reward int not null default 100,
  coin_reward int not null default 10,
  starts_on date,
  ends_on date,
  active boolean not null default true
);

create table if not exists challenge_progress (
  user_id uuid references profiles(id) on delete cascade,
  challenge_id uuid references challenges(id) on delete cascade,
  period_key text not null,
  progress int not null default 0,
  completed_at timestamptz,
  primary key (user_id, challenge_id, period_key)
);

-- ---------------------------------------------------------------- attendance, homework, reports
create table if not exists class_sessions (
  id uuid primary key default gen_random_uuid(),
  course_id uuid references courses(id) on delete set null,
  title text not null,
  held_on date not null default current_date
);

create table if not exists attendance (
  session_id uuid references class_sessions(id) on delete cascade,
  user_id uuid references profiles(id) on delete cascade,
  status text not null check (status in ('present','late','absent','excused')),
  primary key (session_id, user_id)
);

create table if not exists assignments (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references courses(id) on delete cascade,
  chapter_id uuid references chapters(id) on delete set null,
  title text not null,
  kind text not null default 'homework' check (kind in ('homework','worksheet','mock','paper')),
  instructions text,
  file_path text,
  due_at timestamptz,
  max_score int not null default 20,
  xp_reward int not null default 80,
  status pub_status not null default 'published',
  release_at timestamptz,
  answers_released boolean not null default false,
  solution_path text,
  mark_scheme_path text,
  solution_video_url text,
  created_at timestamptz not null default now()
);

create table if not exists submissions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references assignments(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  file_paths text[] not null default '{}',
  text_answer text,
  submitted_at timestamptz not null default now(),
  score int,
  feedback text,
  graded_at timestamptz,
  unique (assignment_id, user_id)
);

create table if not exists tutor_notes (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references profiles(id) on delete cascade,
  body text not null,
  created_at timestamptz not null default now()
);

create table if not exists student_topics (
  student_id uuid references profiles(id) on delete cascade,
  chapter_id uuid references chapters(id) on delete cascade,
  label text not null check (label in ('weak','strong')),
  primary key (student_id, chapter_id)
);

create table if not exists reports (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references profiles(id) on delete cascade,
  period_label text not null,
  parent_name text,
  comment text not null,
  stats jsonb not null default '{}'::jsonb,
  shared_with_student boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists announcements (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  body text not null,
  created_at timestamptz not null default now()
);

create table if not exists notifications (
  id bigserial primary key,
  user_id uuid not null references profiles(id) on delete cascade,
  title text not null,
  body text,
  link text,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists notif_user on notifications(user_id, created_at desc);

-- ---------------------------------------------------------------- battles
create table if not exists battles (
  id uuid primary key default gen_random_uuid(),
  code text unique not null,
  mode text not null check (mode in ('1v1','2v2')),
  course_id uuid references courses(id) on delete set null,
  host_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'lobby' check (status in ('lobby','live','finished','cancelled')),
  round_count int not null default 5,
  round_seconds int not null default 20,
  current_round int not null default 0,
  phase text not null default 'question' check (phase in ('question','reveal')),
  phase_started_at timestamptz,
  winner_team int,
  rewarded boolean not null default false,
  announced boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists battle_players (
  battle_id uuid references battles(id) on delete cascade,
  user_id uuid references profiles(id) on delete cascade,
  team int not null check (team in (1,2)),
  score int not null default 0,
  joined_at timestamptz not null default now(),
  primary key (battle_id, user_id)
);

create table if not exists battle_rounds (
  battle_id uuid references battles(id) on delete cascade,
  round_no int not null,
  question_id uuid not null references questions(id),
  correct int,                     -- filled in only when the round is revealed
  primary key (battle_id, round_no)
);

create table if not exists battle_answers (
  battle_id uuid references battles(id) on delete cascade,
  round_no int not null,
  user_id uuid references profiles(id) on delete cascade,
  choice int,
  correct boolean,
  ms int,
  points int not null default 0,
  revealed boolean not null default false,
  primary key (battle_id, round_no, user_id)
);


-- ===== 0002_game_logic.sql =====
-- Game logic: XP, streaks, challenges, achievements, quizzes, battles.
-- All of these run as SECURITY DEFINER so the browser can never write scores or XP directly.

-- Mauritius local "today" (streaks and daily challenges reset at local midnight)
create or replace function today_local() returns date language sql stable as $$
  select (now() at time zone 'Indian/Mauritius')::date;
$$;

create or replace function period_key(p text) returns text language sql stable as $$
  select case p
    when 'daily' then to_char(today_local(), 'YYYY-MM-DD')
    when 'weekly' then to_char(today_local(), 'IYYY-"W"IW')
    else 'once' end;
$$;

-- ---------------------------------------------------------------- new user -> profile
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  first_user boolean;
begin
  select not exists(select 1 from profiles) into first_user;
  insert into profiles (id, discord_id, discord_username, display_name, discord_avatar_url, role, status)
  values (
    new.id,
    coalesce(meta->>'provider_id', meta->>'sub'),
    coalesce(meta->'custom_claims'->>'global_name', meta->>'name', meta->>'user_name'),
    coalesce(meta->'custom_claims'->>'global_name', meta->>'full_name', meta->>'name', 'New player'),
    meta->>'avatar_url',
    case when first_user then 'tutor'::user_role else 'student'::user_role end,
    case when first_user then 'approved'::account_status else 'pending'::account_status end
  )
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function handle_new_user();

-- ---------------------------------------------------------------- notifications
create or replace function notify(p_user uuid, p_title text, p_body text default null, p_link text default null)
returns void language sql security definer set search_path = public as $$
  insert into notifications(user_id, title, body, link) values (p_user, p_title, p_body, p_link);
$$;

-- ---------------------------------------------------------------- XP
-- Awards XP (and coins) with the level-jump boost: +0.25x per tier the content is above the student.
create or replace function award_xp(
  p_user uuid, p_base int, p_reason text, p_ref text default null,
  p_content_tier tier default null, p_coins int default 0, p_counts_study boolean default true
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  prof profiles%rowtype;
  mult numeric := 1;
  gained int;
  lvl_before int;
  lvl_after int;
  today date := today_local();
  new_day boolean := false;
begin
  select * into prof from profiles where id = p_user for update;
  if not found or (p_base <= 0 and p_coins <= 0 and not p_counts_study) then
    return jsonb_build_object('xp', 0, 'leveled_up', false);
  end if;
  if p_content_tier is not null then
    mult := 1 + 0.25 * greatest(0, tier_rank(p_content_tier) - tier_rank(prof.tier));
  end if;
  gained := round(greatest(p_base, 0) * mult);
  lvl_before := level_from_xp(prof.xp);

  if gained > 0 or p_coins > 0 then
    insert into xp_events(user_id, amount, coins, multiplier, reason, ref)
    values (p_user, gained, p_coins, mult, p_reason, p_ref);
    update profiles set xp = xp + gained, coins = coins + p_coins where id = p_user;
  end if;

  if p_counts_study and (prof.last_study_date is null or prof.last_study_date < today) then
    new_day := true;
    update profiles set
      streak = case when prof.last_study_date = today - 1 then prof.streak + 1 else 1 end,
      best_streak = greatest(prof.best_streak, case when prof.last_study_date = today - 1 then prof.streak + 1 else 1 end),
      last_study_date = today
    where id = p_user;
  end if;

  lvl_after := level_from_xp(prof.xp + gained);
  if lvl_after > lvl_before then
    perform notify(p_user, 'Level up! You reached Lv ' || lvl_after, null, '/dashboard');
  end if;

  if p_reason <> 'challenge' and gained > 0 then
    perform bump_challenge(p_user, 'xp_earned', gained, null);
  end if;
  if new_day then
    perform bump_challenge(p_user, 'study_days', 1, null);
  end if;

  return jsonb_build_object('xp', gained, 'multiplier', mult, 'level_before', lvl_before,
                            'level_after', lvl_after, 'leveled_up', lvl_after > lvl_before);
end $$;

-- ---------------------------------------------------------------- challenges
create or replace function bump_challenge(p_user uuid, p_type text, p_amount int, p_quiz uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  c challenges%rowtype;
  k text;
  prog int;
begin
  for c in
    select * from challenges
    where active and type = p_type
      and (starts_on is null or starts_on <= today_local())
      and (ends_on is null or ends_on >= today_local())
      and (type <> 'quiz_specific' or quiz_id = p_quiz)
  loop
    k := period_key(c.period);
    insert into challenge_progress(user_id, challenge_id, period_key, progress)
    values (p_user, c.id, k, 0) on conflict do nothing;

    update challenge_progress set progress = progress + p_amount
    where user_id = p_user and challenge_id = c.id and period_key = k and completed_at is null
    returning progress into prog;

    if prog is not null and prog >= c.target then
      update challenge_progress set completed_at = now()
      where user_id = p_user and challenge_id = c.id and period_key = k;
      perform award_xp(p_user, c.xp_reward, 'challenge', c.id::text, null, c.coin_reward, false);
      perform notify(p_user, 'Challenge complete: ' || c.title, '+' || c.xp_reward || ' XP', '/challenges');
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------- achievements
create or replace function check_achievements(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  a achievements%rowtype;
  prof profiles%rowtype;
  v int;
  have int;
begin
  select * into prof from profiles where id = p_user;
  for a in
    select * from achievements x where active
      and not exists (select 1 from user_achievements u where u.user_id = p_user and u.achievement_id = x.id)
  loop
    v := (a.criteria->>'value')::int;
    have := case a.criteria->>'type'
      when 'streak' then prof.best_streak
      when 'level' then level_from_xp(prof.xp)
      when 'quizzes_passed' then (select count(distinct quiz_id) from quiz_attempts
          where user_id = p_user and not flagged and total > 0 and score * 2 >= total)
      when 'perfect_quiz' then (select count(*) from quiz_attempts
          where user_id = p_user and not flagged and total > 0 and score = total)
      when 'homework' then (select count(*) from submissions where user_id = p_user)
      when 'battles_won' then (select count(*) from battles b join battle_players p on p.battle_id = b.id
          where p.user_id = p_user and b.status = 'finished' and b.winner_team = p.team)
      when 'battles_played' then (select count(*) from battles b join battle_players p on p.battle_id = b.id
          where p.user_id = p_user and b.status = 'finished')
      when 'attendance' then (select count(*) from attendance where user_id = p_user and status in ('present','late'))
      when 'speedrun_points' then (select coalesce(max(points), 0) from quiz_attempts q join quizzes z on z.id = q.quiz_id
          where q.user_id = p_user and z.kind = 'speedrun' and not q.flagged)
      else 0 end;
    if coalesce(have, 0) >= v then
      insert into user_achievements(user_id, achievement_id) values (p_user, a.id) on conflict do nothing;
      perform award_xp(p_user, a.xp_reward, 'achievement', a.code, null, 0, false);
      perform notify(p_user, 'Achievement unlocked: ' || a.title, a.description, '/achievements');
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------- quizzes
create or replace function start_quiz(p_quiz uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  qz quizzes%rowtype;
  ids uuid[];
  att uuid;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into qz from quizzes where id = p_quiz;
  if not found or not (is_live(qz.status, qz.release_at) or is_tutor()) then
    raise exception 'quiz locked';
  end if;
  if qz.chapter_id is not null and not is_tutor() and not exists (
      select 1 from chapters c where c.id = qz.chapter_id and is_live(c.status, c.release_at)) then
    raise exception 'chapter locked';
  end if;

  if qz.kind = 'speedrun' then
    select array_agg(id) into ids from (
      select q.id from questions q join question_keys k on k.question_id = q.id
      where (q.quiz_id = qz.id) or (qz.chapter_id is null and q.course_id = qz.course_id and q.battle_ok)
      order by random() limit 10) s;
  else
    select array_agg(id) into ids from (
      select q.id from questions q join question_keys k on k.question_id = q.id
      where q.quiz_id = qz.id order by random()) s;
  end if;
  if ids is null then raise exception 'quiz has no questions yet'; end if;

  insert into quiz_attempts(user_id, quiz_id, question_ids) values (auth.uid(), qz.id, ids)
  returning id into att;

  return jsonb_build_object(
    'attempt_id', att, 'kind', qz.kind, 'title', qz.title, 'time_limit_sec', qz.time_limit_sec,
    'questions', (select jsonb_agg(jsonb_build_object('id', q.id, 'prompt', q.prompt, 'options', q.options)
                   order by array_position(ids, q.id))
                  from questions q where q.id = any(ids)));
end $$;

create or replace function submit_quiz(p_attempt uuid, p_answers jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  att quiz_attempts%rowtype;
  qz quizzes%rowtype;
  crs courses%rowtype;
  n int;
  correct_n int := 0;
  elapsed int;
  pts int := 0;
  frac numeric;
  prev numeric;
  xp_base int := 0;
  res jsonb;
  results jsonb;
  is_flagged boolean := false;
  passed_today boolean;
  runs_today int;
begin
  select * into att from quiz_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.finished_at is not null then raise exception 'already submitted'; end if;
  select * into qz from quizzes where id = att.quiz_id;
  select * into crs from courses where id = qz.course_id;

  n := array_length(att.question_ids, 1);
  elapsed := (extract(epoch from (now() - att.started_at)) * 1000)::int;

  select count(*) into correct_n
  from unnest(att.question_ids) qid join question_keys k on k.question_id = qid
  where (p_answers->>(qid::text)) is not null and (p_answers->>(qid::text))::int = k.correct;

  select jsonb_agg(jsonb_build_object(
      'id', q.id, 'choice', (p_answers->>(q.id::text))::int, 'correct', k.correct,
      'right', (p_answers->>(q.id::text))::int = k.correct, 'explanation', q.explanation)
      order by array_position(att.question_ids, q.id))
  into results
  from questions q join question_keys k on k.question_id = q.id where q.id = any(att.question_ids);

  -- anti-cheat: nobody genuinely answers faster than ~1.2 s per question
  if elapsed < 1200 * n then is_flagged := true; end if;
  if qz.time_limit_sec is not null and elapsed > (qz.time_limit_sec + 10) * 1000 then is_flagged := true; end if;

  frac := correct_n::numeric / n;
  pts := correct_n * 100 + floor(greatest(0, n * 15000 - elapsed) / 1000.0 * 10 * frac)::int;

  if not is_flagged then
    if qz.kind = 'quiz' then
      -- only the improvement on your best score pays, so retakes can't farm XP
      select coalesce(max(score::numeric / nullif(total, 0)), 0) into prev
      from quiz_attempts where user_id = att.user_id and quiz_id = qz.id and finished_at is not null and not flagged;
      xp_base := round(qz.xp_reward * greatest(0, frac - prev));
    else
      select count(*) into runs_today from quiz_attempts
      where user_id = att.user_id and quiz_id = qz.id and finished_at is not null and not flagged
        and (finished_at at time zone 'Indian/Mauritius')::date = today_local();
      if runs_today < 3 then xp_base := round(qz.xp_reward * frac); end if;
    end if;
  end if;

  select exists(select 1 from quiz_attempts where user_id = att.user_id and quiz_id = qz.id
      and finished_at is not null and not flagged and score * 2 >= total
      and (finished_at at time zone 'Indian/Mauritius')::date = today_local()) into passed_today;

  update quiz_attempts set finished_at = now(), score = correct_n, total = n, time_ms = elapsed,
    points = pts, flagged = is_flagged, answers = p_answers
  where id = att.id;

  res := award_xp(att.user_id, xp_base, 'quiz', qz.id::text, crs.tier, case when xp_base > 0 then 5 else 0 end, true);
  update quiz_attempts set xp_awarded = coalesce((res->>'xp')::int, 0) where id = att.id;

  if not is_flagged and frac >= 0.5 and not passed_today then
    perform bump_challenge(att.user_id, 'quiz_pass', 1, null);
    perform bump_challenge(att.user_id, 'quiz_specific', 1, qz.id);
  end if;
  perform check_achievements(att.user_id);

  return jsonb_build_object('score', correct_n, 'total', n, 'points', pts, 'time_ms', elapsed,
    'flagged', is_flagged, 'xp', coalesce((res->>'xp')::int, 0), 'multiplier', res->'multiplier',
    'leveled_up', coalesce((res->>'leveled_up')::boolean, false), 'level_after', res->'level_after',
    'results', results);
end $$;

-- ---------------------------------------------------------------- tutor tools (called from the server with a tutor check)
create or replace function tutor_award(p_user uuid, p_xp int, p_coins int, p_reason text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare r jsonb;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  r := award_xp(p_user, p_xp, 'bonus', p_reason, null, p_coins, false);
  perform notify(p_user, 'Bonus from your tutor: +' || p_xp || ' XP', p_reason, '/dashboard');
  perform check_achievements(p_user);
  return r;
end $$;

create or replace function mark_attendance(p_session uuid, p_user uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
declare old text;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  select status into old from attendance where session_id = p_session and user_id = p_user;
  insert into attendance(session_id, user_id, status) values (p_session, p_user, p_status)
  on conflict (session_id, user_id) do update set status = excluded.status;
  if (old is null or old in ('absent','excused')) and p_status in ('present','late') then
    perform award_xp(p_user, case when p_status = 'present' then 40 else 20 end, 'attendance', p_session::text, null, 5, true);
    perform bump_challenge(p_user, 'attendance', 1, null);
    perform check_achievements(p_user);
  end if;
end $$;

create or replace function grade_submission(p_submission uuid, p_score int, p_feedback text)
returns void language plpgsql security definer set search_path = public as $$
declare s submissions%rowtype; a assignments%rowtype; c courses%rowtype; first_grade boolean;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  select * into s from submissions where id = p_submission for update;
  select * into a from assignments where id = s.assignment_id;
  select * into c from courses where id = a.course_id;
  first_grade := s.graded_at is null;
  update submissions set score = p_score, feedback = p_feedback, graded_at = now() where id = s.id;
  if first_grade then
    perform award_xp(s.user_id, round(a.xp_reward * least(1, greatest(0, p_score::numeric / a.max_score)))::int
                     + 20, 'homework', a.id::text, c.tier, 10, true);
    if a.due_at is null or s.submitted_at <= a.due_at then
      perform bump_challenge(s.user_id, 'homework_on_time', 1, null);
    end if;
    perform check_achievements(s.user_id);
  end if;
  perform notify(s.user_id, 'Marked: ' || a.title, p_score || ' / ' || a.max_score, '/homework');
end $$;

-- ---------------------------------------------------------------- leaderboards & public cards
create or replace function profile_cards(p_ids uuid[]) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, tier tier)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp), p.tier
  from profiles p where p.id = any(p_ids) and is_approved();
$$;

create or replace function get_leaderboard(p_kind text, p_limit int default 50) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, value bigint)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp),
         case p_kind
           when 'xp' then p.xp::bigint
           when 'monthly' then (select coalesce(sum(amount), 0) from xp_events e where e.user_id = p.id
                                  and e.created_at >= date_trunc('month', now()))
           when 'attendance' then (select count(*) from attendance a where a.user_id = p.id and a.status in ('present','late'))
           when 'speedrun' then (select coalesce(max(q.points), 0) from quiz_attempts q join quizzes z on z.id = q.quiz_id
                                  where q.user_id = p.id and z.kind = 'speedrun' and not q.flagged)
           when 'battles' then (select count(*) from battles b join battle_players bp on bp.battle_id = b.id
                                  where bp.user_id = p.id and b.status = 'finished' and b.winner_team = bp.team)
           else 0 end as value
  from profiles p
  where p.status = 'approved' and p.role = 'student' and is_approved()
  order by value desc, p.xp desc
  limit p_limit;
$$;

-- ---------------------------------------------------------------- battles
create or replace function create_battle(p_mode text, p_course uuid default null, p_rounds int default 5)
returns text language plpgsql security definer set search_path = public as $$
declare c text; b uuid;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_mode not in ('1v1','2v2') then raise exception 'bad mode'; end if;
  loop
    c := upper(substr(md5(random()::text), 1, 5));
    exit when not exists (select 1 from battles where code = c);
  end loop;
  insert into battles(code, mode, course_id, host_id, round_count)
  values (c, p_mode, p_course, auth.uid(), least(greatest(coalesce(p_rounds, 5), 3), 10))
  returning id into b;
  insert into battle_players(battle_id, user_id, team) values (b, auth.uid(), 1);
  return c;
end $$;

create or replace function join_battle(p_code text, p_team int default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; cap int; t int; n1 int; n2 int;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into b from battles where code = upper(p_code) for update;
  if not found then raise exception 'battle not found'; end if;
  if exists(select 1 from battle_players where battle_id = b.id and user_id = auth.uid()) then
    if b.status = 'lobby' and p_team in (1,2) then
      cap := case b.mode when '1v1' then 1 else 2 end;
      if (select count(*) from battle_players where battle_id = b.id and team = p_team and user_id <> auth.uid()) < cap then
        update battle_players set team = p_team where battle_id = b.id and user_id = auth.uid();
      end if;
    end if;
    return b.id;
  end if;
  if b.status <> 'lobby' then raise exception 'battle already started'; end if;
  cap := case b.mode when '1v1' then 1 else 2 end;
  select count(*) filter (where team = 1), count(*) filter (where team = 2) into n1, n2
  from battle_players where battle_id = b.id;
  t := coalesce(p_team, case when n1 <= n2 then 1 else 2 end);
  if (t = 1 and n1 >= cap) then t := 2; end if;
  if (t = 2 and n2 >= cap) then t := 1; end if;
  if (t = 1 and n1 >= cap) or (t = 2 and n2 >= cap) then raise exception 'battle is full'; end if;
  insert into battle_players(battle_id, user_id, team) values (b.id, auth.uid(), t);
  return b.id;
end $$;

create or replace function leave_battle(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype;
begin
  select * into b from battles where id = p_battle for update;
  if b.status <> 'lobby' then raise exception 'battle already started'; end if;
  if b.host_id = auth.uid() then
    update battles set status = 'cancelled' where id = b.id;
  else
    delete from battle_players where battle_id = b.id and user_id = auth.uid();
  end if;
end $$;

create or replace function start_battle(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; i int := 0; q uuid;
begin
  select * into b from battles where id = p_battle for update;
  if b.host_id <> auth.uid() then raise exception 'only the host can start'; end if;
  if b.status <> 'lobby' then raise exception 'already started'; end if;
  if (select count(distinct team) from battle_players where battle_id = b.id) < 2 then
    raise exception 'both teams need at least one player';
  end if;
  for q in
    select qq.id from questions qq join question_keys k on k.question_id = qq.id
    where qq.battle_ok and (b.course_id is null or qq.course_id = b.course_id)
    order by random() limit b.round_count
  loop
    i := i + 1;
    insert into battle_rounds(battle_id, round_no, question_id) values (b.id, i, q);
  end loop;
  if i = 0 then raise exception 'no questions available for this course'; end if;
  update battles set status = 'live', round_count = i, current_round = 1, phase = 'question',
    phase_started_at = now() where id = b.id;
end $$;

-- question for the current round (no answer key)
create or replace function battle_question(p_battle uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('round', r.round_no, 'id', q.id, 'prompt', q.prompt, 'options', q.options, 'correct', r.correct)
  from battles b join battle_rounds r on r.battle_id = b.id and r.round_no = b.current_round
  join questions q on q.id = r.question_id
  where b.id = p_battle and exists(select 1 from battle_players p where p.battle_id = b.id and p.user_id = auth.uid());
$$;

create or replace function battle_reveal(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; k int;
begin
  select * into b from battles where id = p_battle;
  select qk.correct into k from battle_rounds r join question_keys qk on qk.question_id = r.question_id
  where r.battle_id = b.id and r.round_no = b.current_round;
  update battle_rounds set correct = k where battle_id = b.id and round_no = b.current_round;
  update battle_answers set revealed = true where battle_id = b.id and round_no = b.current_round;
  update battle_players p set score = p.score + coalesce((select a.points from battle_answers a
      where a.battle_id = b.id and a.round_no = b.current_round and a.user_id = p.user_id), 0)
  where p.battle_id = b.id;
  update battles set phase = 'reveal', phase_started_at = now() where id = b.id;
end $$;

create or replace function battle_finish(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; s1 int; s2 int; w int; pl record; c courses%rowtype; played_today int; nplayers int;
begin
  select * into b from battles where id = p_battle for update;
  select coalesce(sum(score) filter (where team = 1), 0), coalesce(sum(score) filter (where team = 2), 0), count(*)
    into s1, s2, nplayers from battle_players where battle_id = b.id;
  w := case when s1 > s2 then 1 when s2 > s1 then 2 else 0 end;
  update battles set status = 'finished', winner_team = w where id = b.id;
  if b.rewarded then return; end if;
  update battles set rewarded = true where id = b.id;
  select * into c from courses where id = b.course_id;
  for pl in select * from battle_players where battle_id = b.id loop
    select count(*) into played_today from xp_events
      where user_id = pl.user_id and reason = 'battle' and (created_at at time zone 'Indian/Mauritius')::date = today_local();
    if nplayers >= 2 and played_today < 5 then
      perform award_xp(pl.user_id, case when w = 0 then 35 when w = pl.team then 60 else 20 end,
                       'battle', b.id::text, c.tier, case when w = pl.team then 10 else 3 end, true);
    end if;
    perform bump_challenge(pl.user_id, 'battle_play', 1, null);
    if w = pl.team then perform bump_challenge(pl.user_id, 'battle_win', 1, null); end if;
    perform check_achievements(pl.user_id);
  end loop;
end $$;

create or replace function answer_battle(p_battle uuid, p_choice int) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; k int; elapsed int; pts int := 0; ok boolean;
begin
  select * into b from battles where id = p_battle for update;
  if b.status <> 'live' or b.phase <> 'question' then raise exception 'not accepting answers'; end if;
  if not exists(select 1 from battle_players where battle_id = b.id and user_id = auth.uid()) then
    raise exception 'not in this battle';
  end if;
  elapsed := (extract(epoch from (now() - b.phase_started_at)) * 1000)::int;
  if elapsed > (b.round_seconds + 1) * 1000 then raise exception 'too late'; end if;
  select qk.correct into k from battle_rounds r join question_keys qk on qk.question_id = r.question_id
  where r.battle_id = b.id and r.round_no = b.current_round;
  ok := p_choice = k;
  if ok then pts := 100 + greatest(0, round(100 * (1 - elapsed::numeric / (b.round_seconds * 1000))))::int; end if;
  insert into battle_answers(battle_id, round_no, user_id, choice, correct, ms, points)
  values (b.id, b.current_round, auth.uid(), p_choice, ok, elapsed, pts)
  on conflict do nothing;
  if (select count(*) from battle_answers where battle_id = b.id and round_no = b.current_round)
     >= (select count(*) from battle_players where battle_id = b.id) then
    perform battle_reveal(b.id);
  end if;
end $$;

-- clients call this every second; it moves the battle on when timers run out
create or replace function tick_battle(p_battle uuid) returns text
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype;
begin
  select * into b from battles where id = p_battle for update;
  if not found or b.status <> 'live' then return coalesce(b.status, 'missing'); end if;
  if not exists(select 1 from battle_players where battle_id = b.id and user_id = auth.uid()) then
    return b.status;
  end if;
  if b.phase = 'question' and now() > b.phase_started_at + make_interval(secs => b.round_seconds + 1) then
    perform battle_reveal(b.id);
  elsif b.phase = 'reveal' and now() > b.phase_started_at + interval '5 seconds' then
    if b.current_round >= b.round_count then
      perform battle_finish(b.id);
      return 'finished';
    end if;
    update battles set current_round = current_round + 1, phase = 'question', phase_started_at = now() where id = b.id;
  end if;
  return 'live';
end $$;

-- ---------------------------------------------------------------- execute permissions
-- internal helpers are not callable from the browser
revoke execute on function award_xp(uuid,int,text,text,tier,int,boolean) from public, anon, authenticated;
revoke execute on function bump_challenge(uuid,text,int,uuid) from public, anon, authenticated;
revoke execute on function check_achievements(uuid) from public, anon, authenticated;
revoke execute on function notify(uuid,text,text,text) from public, anon, authenticated;
revoke execute on function battle_reveal(uuid) from public, anon, authenticated;
revoke execute on function battle_finish(uuid) from public, anon, authenticated;
revoke execute on function handle_new_user() from public, anon, authenticated;


-- ===== 0003_security.sql =====
-- Row level security, column privileges, storage buckets and realtime.

alter table profiles enable row level security;
alter table courses enable row level security;
alter table chapters enable row level security;
alter table parts enable row level security;
alter table resources enable row level security;
alter table quizzes enable row level security;
alter table questions enable row level security;
alter table question_keys enable row level security;
alter table quiz_attempts enable row level security;
alter table xp_events enable row level security;
alter table achievements enable row level security;
alter table user_achievements enable row level security;
alter table challenges enable row level security;
alter table challenge_progress enable row level security;
alter table class_sessions enable row level security;
alter table attendance enable row level security;
alter table assignments enable row level security;
alter table submissions enable row level security;
alter table tutor_notes enable row level security;
alter table student_topics enable row level security;
alter table reports enable row level security;
alter table announcements enable row level security;
alter table notifications enable row level security;
alter table battles enable row level security;
alter table battle_players enable row level security;
alter table battle_rounds enable row level security;
alter table battle_answers enable row level security;

-- profiles: you see yourself; the tutor sees everyone. Other students' public cards come from profile_cards().
-- Explicit table access, so the app works whether or not "Grant API access to new tables
-- automatically" was ticked when the project was created. RLS below still decides which ROWS.
grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant select on all tables in schema public to authenticated;

create policy profiles_select on profiles for select using (id = auth.uid() or is_tutor());
create policy profiles_update_self on profiles for update using (id = auth.uid()) with check (id = auth.uid());
-- students may only change these columns themselves (everything else goes through the server)
revoke update on profiles from authenticated, anon;
grant update (display_name, theme, avatar_mode, blocky, contact) on profiles to authenticated;

-- content: drafts are invisible; locked/scheduled items show as locked; bodies only when live
create policy courses_select on courses for select using (is_approved() and (active or is_tutor()));
create policy chapters_select on chapters for select using (is_tutor() or (is_approved() and status <> 'draft'));
create policy parts_select on parts for select using (
  is_tutor() or (is_approved() and is_live(status, release_at)
    and exists (select 1 from chapters c where c.id = chapter_id and is_live(c.status, c.release_at))));
create policy resources_select on resources for select using (
  is_tutor() or (is_approved() and is_live(status, release_at)
    and (chapter_id is null or exists (select 1 from chapters c where c.id = chapter_id and is_live(c.status, c.release_at)))));
create policy quizzes_select on quizzes for select using (is_tutor() or (is_approved() and status <> 'draft'));
create policy questions_select on questions for select using (
  is_tutor() or (is_approved() and quiz_id is not null
    and exists (select 1 from quizzes z where z.id = quiz_id and is_live(z.status, z.release_at))));
create policy keys_tutor on question_keys for select using (is_tutor());

create policy attempts_select on quiz_attempts for select using (user_id = auth.uid() or is_tutor());
create policy xp_select on xp_events for select using (user_id = auth.uid() or is_tutor());
create policy ach_select on achievements for select using (is_approved());
create policy uach_select on user_achievements for select using (user_id = auth.uid() or is_tutor());
create policy ch_select on challenges for select using (is_approved() and (active or is_tutor()));
create policy chp_select on challenge_progress for select using (user_id = auth.uid() or is_tutor());

create policy sessions_select on class_sessions for select using (is_approved());
create policy att_select on attendance for select using (user_id = auth.uid() or is_tutor());
create policy asg_select on assignments for select using (is_tutor() or (is_approved() and is_live(status, release_at)));
create policy sub_select on submissions for select using (user_id = auth.uid() or is_tutor());

create policy notes_tutor on tutor_notes for select using (is_tutor());
create policy topics_select on student_topics for select using (student_id = auth.uid() or is_tutor());
create policy reports_select on reports for select using (is_tutor() or (student_id = auth.uid() and shared_with_student));
create policy ann_select on announcements for select using (is_approved());

create policy notif_select on notifications for select using (user_id = auth.uid());
create policy notif_update on notifications for update using (user_id = auth.uid()) with check (user_id = auth.uid());
revoke update on notifications from authenticated, anon;
grant update (read_at) on notifications to authenticated;

-- battles: lobbies are visible to approved players; rounds/answers only to participants;
-- an answer stays hidden from others until its round is revealed
create policy battles_select on battles for select using (is_approved());
create policy bp_select on battle_players for select using (is_approved());
create policy br_select on battle_rounds for select using (
  exists (select 1 from battle_players p where p.battle_id = battle_rounds.battle_id and p.user_id = auth.uid()) or is_tutor());
create policy ba_select on battle_answers for select using (
  (user_id = auth.uid() or revealed or is_tutor())
  and exists (select 1 from battle_players p where p.battle_id = battle_answers.battle_id and p.user_id = auth.uid()));

-- No insert/update/delete policies exist for students on any other table:
-- every write goes through SECURITY DEFINER functions or the server (service role).

-- ---------------------------------------------------------------- storage (private buckets; files are served with signed URLs from the server)
insert into storage.buckets (id, name, public) values
  ('resources', 'resources', false),
  ('submissions', 'submissions', false),
  ('solutions', 'solutions', false)
on conflict (id) do nothing;
-- 25 MB per file; uploads go straight from the browser to storage with one-time signed upload URLs
update storage.buckets set file_size_limit = 26214400 where id in ('resources','submissions','solutions');

-- ---------------------------------------------------------------- realtime
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table battles, battle_players, battle_answers, battle_rounds, notifications;
  end if;
exception when duplicate_object then null; end $$;


-- ===== 0004_topic_levels.sql =====
-- Adds a middle option for topic ratings: weak (needs work) / average / strong.
alter table student_topics drop constraint if exists student_topics_label_check;
alter table student_topics add constraint student_topics_label_check check (label in ('weak', 'average', 'strong'));


-- ===== 0005_exam_and_review.sql =====
-- Exam mode (timed Paper 1 practice) and the mistakes deck (spaced review of wrong answers).

-- ---------------------------------------------------------------- quiz kinds
alter table quizzes drop constraint if exists quizzes_kind_check;
alter table quizzes add constraint quizzes_kind_check check (kind in ('quiz', 'speedrun', 'exam', 'review'));
alter table quizzes add column if not exists question_count int;   -- exams: how many questions to draw

-- ---------------------------------------------------------------- mistakes deck
-- box 0 = due 1 day after the mistake, box 1 = 3 days, box 2 = 7 days; right again in box 2 = mastered (row deleted)
create table if not exists review_items (
  user_id uuid not null references profiles(id) on delete cascade,
  question_id uuid not null references questions(id) on delete cascade,
  course_id uuid not null references courses(id) on delete cascade,
  box int not null default 0,
  due_at timestamptz not null,
  times_wrong int not null default 1,
  updated_at timestamptz not null default now(),
  primary key (user_id, question_id)
);
create index if not exists review_due on review_items(user_id, course_id, due_at);
alter table review_items enable row level security;
drop policy if exists ri_select on review_items;
create policy ri_select on review_items for select using (user_id = auth.uid() or is_tutor());
grant select on review_items to authenticated;
grant all on review_items to service_role;

-- ---------------------------------------------------------------- start_quiz (adds exam + review)
create or replace function start_quiz(p_quiz uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  qz quizzes%rowtype;
  ids uuid[];
  att uuid;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into qz from quizzes where id = p_quiz;
  if not found or not (is_live(qz.status, qz.release_at) or is_tutor()) then
    raise exception 'quiz locked';
  end if;
  if qz.chapter_id is not null and not is_tutor() and not exists (
      select 1 from chapters c where c.id = qz.chapter_id and is_live(c.status, c.release_at)) then
    raise exception 'chapter locked';
  end if;

  if qz.kind = 'speedrun' then
    select array_agg(id) into ids from (
      select q.id from questions q join question_keys k on k.question_id = q.id
      where (q.quiz_id = qz.id) or (qz.chapter_id is null and q.course_id = qz.course_id and q.battle_ok)
      order by random() limit 10) s;
  elsif qz.kind = 'exam' then
    -- random questions from every released chapter of the course
    select array_agg(id) into ids from (
      select q.id from questions q
      join question_keys k on k.question_id = q.id
      join chapters c on c.id = q.chapter_id
      where q.course_id = qz.course_id and (is_live(c.status, c.release_at) or is_tutor())
      order by random() limit coalesce(qz.question_count, 40)) s;
  elsif qz.kind = 'review' then
    select array_agg(question_id) into ids from (
      select r.question_id from review_items r join question_keys k on k.question_id = r.question_id
      where r.user_id = auth.uid() and r.course_id = qz.course_id and r.due_at <= now()
      order by r.due_at limit 10) s;
    if ids is null then raise exception 'nothing to review'; end if;
  else
    select array_agg(id) into ids from (
      select q.id from questions q join question_keys k on k.question_id = q.id
      where q.quiz_id = qz.id order by random()) s;
  end if;
  if ids is null then raise exception 'quiz has no questions yet'; end if;

  insert into quiz_attempts(user_id, quiz_id, question_ids) values (auth.uid(), qz.id, ids)
  returning id into att;

  return jsonb_build_object(
    'attempt_id', att, 'kind', qz.kind, 'title', qz.title, 'time_limit_sec', qz.time_limit_sec,
    'questions', (select jsonb_agg(jsonb_build_object('id', q.id, 'prompt', q.prompt, 'options', q.options)
                   order by array_position(ids, q.id))
                  from questions q where q.id = any(ids)));
end $$;

-- ---------------------------------------------------------------- submit_quiz (adds exam XP, review XP and the mistakes deck)
create or replace function submit_quiz(p_attempt uuid, p_answers jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  att quiz_attempts%rowtype;
  qz quizzes%rowtype;
  crs courses%rowtype;
  n int;
  correct_n int := 0;
  elapsed int;
  pts int := 0;
  frac numeric;
  prev numeric;
  xp_base int := 0;
  res jsonb;
  results jsonb;
  is_flagged boolean := false;
  passed_today boolean;
  runs_today int;
  r record;
  added int := 0;
  mastered int := 0;
begin
  select * into att from quiz_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.finished_at is not null then raise exception 'already submitted'; end if;
  select * into qz from quizzes where id = att.quiz_id;
  select * into crs from courses where id = qz.course_id;

  n := array_length(att.question_ids, 1);
  elapsed := (extract(epoch from (now() - att.started_at)) * 1000)::int;

  select count(*) into correct_n
  from unnest(att.question_ids) qid join question_keys k on k.question_id = qid
  where (p_answers->>(qid::text)) is not null and (p_answers->>(qid::text))::int = k.correct;

  select jsonb_agg(jsonb_build_object(
      'id', q.id, 'choice', (p_answers->>(q.id::text))::int, 'correct', k.correct,
      'right', coalesce((p_answers->>(q.id::text))::int = k.correct, false), 'explanation', q.explanation)
      order by array_position(att.question_ids, q.id))
  into results
  from questions q join question_keys k on k.question_id = q.id where q.id = any(att.question_ids);

  -- anti-cheat: nobody genuinely answers faster than ~1.2 s per question; overtime also flags
  if elapsed < 1200 * n then is_flagged := true; end if;
  if qz.time_limit_sec is not null and elapsed > (qz.time_limit_sec + 15) * 1000 then is_flagged := true; end if;

  frac := correct_n::numeric / n;
  pts := correct_n * 100 + floor(greatest(0, n * 15000 - elapsed) / 1000.0 * 10 * frac)::int;

  if not is_flagged then
    if qz.kind = 'quiz' then
      -- only the improvement on your best score pays, so retakes can't farm XP
      select coalesce(max(score::numeric / nullif(total, 0)), 0) into prev
      from quiz_attempts where user_id = att.user_id and quiz_id = qz.id and finished_at is not null and not flagged;
      xp_base := round(qz.xp_reward * greatest(0, frac - prev));
    elsif qz.kind = 'review' then
      -- 5 XP per mistake fixed; items only come back on a schedule, so this can't be farmed
      xp_base := correct_n * 5;
    else
      -- speedrun: first 3 runs a day pay; exam: first 2 a day pay
      select count(*) into runs_today from quiz_attempts
      where user_id = att.user_id and quiz_id = qz.id and finished_at is not null and not flagged
        and (finished_at at time zone 'Indian/Mauritius')::date = today_local();
      if runs_today < (case when qz.kind = 'exam' then 2 else 3 end) then xp_base := round(qz.xp_reward * frac); end if;
    end if;

    -- mistakes deck
    for r in
      select qid, (p_answers->>(qid::text)) is not null and (p_answers->>(qid::text))::int = k.correct as ok
      from unnest(att.question_ids) qid join question_keys k on k.question_id = qid
    loop
      if not r.ok then
        insert into review_items(user_id, question_id, course_id, box, due_at)
        values (att.user_id, r.qid, qz.course_id, 0, now() + interval '1 day')
        on conflict (user_id, question_id) do update
          set box = 0, due_at = now() + interval '1 day', times_wrong = review_items.times_wrong + 1, updated_at = now();
        added := added + 1;
      elsif qz.kind = 'review' then
        update review_items set box = box + 1, updated_at = now(),
          due_at = now() + case box when 0 then interval '3 days' else interval '7 days' end
        where user_id = att.user_id and question_id = r.qid;
        delete from review_items where user_id = att.user_id and question_id = r.qid and box >= 3;
        if found then mastered := mastered + 1; end if;
      end if;
    end loop;
  end if;

  select exists(select 1 from quiz_attempts where user_id = att.user_id and quiz_id = qz.id
      and finished_at is not null and not flagged and score * 2 >= total
      and (finished_at at time zone 'Indian/Mauritius')::date = today_local()) into passed_today;

  update quiz_attempts set finished_at = now(), score = correct_n, total = n, time_ms = elapsed,
    points = pts, flagged = is_flagged, answers = p_answers
  where id = att.id;

  res := award_xp(att.user_id, xp_base, 'quiz', qz.id::text, crs.tier, case when xp_base > 0 then 5 else 0 end, true);
  update quiz_attempts set xp_awarded = coalesce((res->>'xp')::int, 0) where id = att.id;

  if not is_flagged and frac >= 0.5 and not passed_today then
    perform bump_challenge(att.user_id, 'quiz_pass', 1, null);
    perform bump_challenge(att.user_id, 'quiz_specific', 1, qz.id);
  end if;
  perform check_achievements(att.user_id);

  return jsonb_build_object('score', correct_n, 'total', n, 'points', pts, 'time_ms', elapsed,
    'flagged', is_flagged, 'xp', coalesce((res->>'xp')::int, 0), 'multiplier', res->'multiplier',
    'leveled_up', coalesce((res->>'leveled_up')::boolean, false), 'level_after', res->'level_after',
    'review_added', added, 'review_mastered', mastered, 'results', results);
end $$;


-- ===== 0006_shop.sql =====
-- Coin shop: cosmetic items, owned items, equipped cosmetics, streak freezes.

alter table profiles add column if not exists name_style text;            -- shop item code
alter table profiles add column if not exists frame text;                 -- shop item code
alter table profiles add column if not exists streak_freezes int not null default 0;

create table if not exists shop_items (
  id uuid primary key default gen_random_uuid(),
  code text not null,
  kind text not null check (kind in ('title', 'name_style', 'frame', 'hat', 'pattern', 'streak_freeze')),
  name text not null,
  description text,
  price int not null check (price >= 0),
  rarity text not null default 'common' check (rarity in ('common', 'rare', 'epic', 'legendary')),
  min_level int not null default 1,
  data jsonb not null default '{}'::jsonb,     -- e.g. {"text": "Ledger Legend"} for titles
  active boolean not null default true,
  sort int not null default 0,
  unique (kind, code)
);

create table if not exists user_items (
  user_id uuid not null references profiles(id) on delete cascade,
  item_id uuid not null references shop_items(id) on delete cascade,
  acquired_at timestamptz not null default now(),
  primary key (user_id, item_id)
);

alter table shop_items enable row level security;
alter table user_items enable row level security;
drop policy if exists shop_select on shop_items;
create policy shop_select on shop_items for select using (is_approved() and (active or is_tutor()));
drop policy if exists ui_select on user_items;
create policy ui_select on user_items for select using (user_id = auth.uid() or is_tutor());
grant select on shop_items, user_items to authenticated;
grant all on shop_items, user_items to service_role;

-- Avatar changes now go through the server (which checks hats/backgrounds are unlocked),
-- so students can no longer write the blocky column directly.
revoke update on profiles from authenticated, anon;
grant update (display_name, theme, avatar_mode, contact) on profiles to authenticated;

-- ---------------------------------------------------------------- buy
create or replace function buy_item(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype; prof profiles%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into it from shop_items where id = p_item and active;
  if not found then raise exception 'item not available'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if level_from_xp(prof.xp) < it.min_level then raise exception 'reach level % to unlock this', it.min_level; end if;
  if prof.coins < it.price then raise exception 'not enough coins'; end if;

  if it.kind = 'streak_freeze' then
    if prof.streak_freezes >= 2 then raise exception 'you can only hold 2 streak freezes'; end if;
    update profiles set coins = coins - it.price, streak_freezes = streak_freezes + 1 where id = prof.id;
  else
    if exists (select 1 from user_items where user_id = prof.id and item_id = it.id) then raise exception 'you already own this'; end if;
    insert into user_items(user_id, item_id) values (prof.id, it.id);
    update profiles set coins = coins - it.price where id = prof.id;
  end if;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, 0, -it.price, 'shop', it.code);
  return jsonb_build_object('coins', prof.coins - it.price, 'kind', it.kind, 'code', it.code);
end $$;

-- ---------------------------------------------------------------- equip (p_code null = take off)
create or replace function equip_item(p_kind text, p_code text) returns void
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_kind not in ('title', 'name_style', 'frame', 'hat', 'pattern') then raise exception 'bad kind'; end if;
  if p_code is not null then
    select s.* into it from shop_items s join user_items u on u.item_id = s.id and u.user_id = auth.uid()
    where s.code = p_code and s.kind = p_kind;
    if not found then raise exception 'you do not own this'; end if;
  end if;
  if p_kind = 'title' then update profiles set title = it.data->>'text' where id = auth.uid();
  elsif p_kind = 'name_style' then update profiles set name_style = p_code where id = auth.uid();
  elsif p_kind = 'frame' then update profiles set frame = p_code where id = auth.uid();
  elsif p_kind = 'hat' then update profiles set blocky = blocky || jsonb_build_object('hat', coalesce(p_code, 'none')) where id = auth.uid();
  elsif p_kind = 'pattern' then update profiles set blocky = blocky || jsonb_build_object('pattern', coalesce(p_code, 'none')) where id = auth.uid();
  end if;
end $$;

-- ---------------------------------------------------------------- streak freezes inside award_xp
create or replace function award_xp(
  p_user uuid, p_base int, p_reason text, p_ref text default null,
  p_content_tier tier default null, p_coins int default 0, p_counts_study boolean default true
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  prof profiles%rowtype;
  mult numeric := 1;
  gained int;
  lvl_before int;
  lvl_after int;
  today date := today_local();
  new_day boolean := false;
  missed int;
  keeps boolean;
begin
  select * into prof from profiles where id = p_user for update;
  if not found or (p_base <= 0 and p_coins <= 0 and not p_counts_study) then
    return jsonb_build_object('xp', 0, 'leveled_up', false);
  end if;
  if p_content_tier is not null then
    mult := 1 + 0.25 * greatest(0, tier_rank(p_content_tier) - tier_rank(prof.tier));
  end if;
  gained := round(greatest(p_base, 0) * mult);
  lvl_before := level_from_xp(prof.xp);

  if gained > 0 or p_coins > 0 then
    insert into xp_events(user_id, amount, coins, multiplier, reason, ref)
    values (p_user, gained, p_coins, mult, p_reason, p_ref);
    update profiles set xp = xp + gained, coins = coins + p_coins where id = p_user;
  end if;

  if p_counts_study and (prof.last_study_date is null or prof.last_study_date < today) then
    new_day := true;
    missed := case when prof.last_study_date is null then 999 else today - prof.last_study_date - 1 end;
    -- streak continues if no day was missed, or if streak freezes cover every missed day
    keeps := missed = 0 or (missed between 1 and prof.streak_freezes and prof.streak > 0);
    update profiles set
      streak = case when keeps then prof.streak + 1 else 1 end,
      best_streak = greatest(prof.best_streak, case when keeps then prof.streak + 1 else 1 end),
      streak_freezes = case when keeps and missed > 0 then prof.streak_freezes - missed else prof.streak_freezes end,
      last_study_date = today
    where id = p_user;
    if keeps and missed > 0 then
      perform notify(p_user, '🧊 Streak freeze used', 'You missed ' || missed || ' day' || case when missed > 1 then 's' else '' end
        || ', but your ' || (prof.streak + 1) || '-day streak survived.', '/shop');
    end if;
  end if;

  lvl_after := level_from_xp(prof.xp + gained);
  if lvl_after > lvl_before then
    perform notify(p_user, 'Level up! You reached Lv ' || lvl_after, null, '/dashboard');
  end if;

  if p_reason <> 'challenge' and gained > 0 then
    perform bump_challenge(p_user, 'xp_earned', gained, null);
  end if;
  if new_day then
    perform bump_challenge(p_user, 'study_days', 1, null);
  end if;

  return jsonb_build_object('xp', gained, 'multiplier', mult, 'level_before', lvl_before,
                            'level_after', lvl_after, 'leveled_up', lvl_after > lvl_before);
end $$;
revoke execute on function award_xp(uuid,int,text,text,tier,int,boolean) from public, anon, authenticated;

-- ---------------------------------------------------------------- public cards now carry cosmetics
drop function if exists profile_cards(uuid[]);
create function profile_cards(p_ids uuid[]) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, tier tier, name_style text, frame text)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp), p.tier, p.name_style, p.frame
  from profiles p where p.id = any(p_ids) and is_approved();
$$;

drop function if exists get_leaderboard(text, int);
create function get_leaderboard(p_kind text, p_limit int default 50) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, value bigint, name_style text, frame text)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp),
         case p_kind
           when 'xp' then p.xp::bigint
           when 'monthly' then (select coalesce(sum(amount), 0) from xp_events e where e.user_id = p.id
                                  and e.created_at >= date_trunc('month', now()))
           when 'attendance' then (select count(*) from attendance a where a.user_id = p.id and a.status in ('present','late'))
           when 'speedrun' then (select coalesce(max(q.points), 0) from quiz_attempts q join quizzes z on z.id = q.quiz_id
                                  where q.user_id = p.id and z.kind = 'speedrun' and not q.flagged)
           when 'battles' then (select count(*) from battles b join battle_players bp on bp.battle_id = b.id
                                  where bp.user_id = p.id and b.status = 'finished' and b.winner_team = bp.team)
           else 0 end as value,
         p.name_style, p.frame
  from profiles p
  where p.status = 'approved' and p.role = 'student' and is_approved()
  order by value desc, p.xp desc
  limit p_limit;
$$;


-- ===== 0007_owner_items.sql =====
-- Owner-exclusive cosmetics: never sold, hidden from students, automatically available to the tutor.
alter table shop_items add column if not exists tutor_only boolean not null default false;

drop policy if exists shop_select on shop_items;
create policy shop_select on shop_items for select using (
  is_approved() and ((active and not tutor_only) or is_tutor()));

create or replace function buy_item(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype; prof profiles%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into it from shop_items where id = p_item and active and not tutor_only;
  if not found then raise exception 'item not available'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if level_from_xp(prof.xp) < it.min_level then raise exception 'reach level % to unlock this', it.min_level; end if;
  if prof.coins < it.price then raise exception 'not enough coins'; end if;
  if it.kind = 'streak_freeze' then
    if prof.streak_freezes >= 2 then raise exception 'you can only hold 2 streak freezes'; end if;
    update profiles set coins = coins - it.price, streak_freezes = streak_freezes + 1 where id = prof.id;
  else
    if exists (select 1 from user_items where user_id = prof.id and item_id = it.id) then raise exception 'you already own this'; end if;
    insert into user_items(user_id, item_id) values (prof.id, it.id);
    update profiles set coins = coins - it.price where id = prof.id;
  end if;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, 0, -it.price, 'shop', it.code);
  return jsonb_build_object('coins', prof.coins - it.price, 'kind', it.kind, 'code', it.code);
end $$;

create or replace function equip_item(p_kind text, p_code text) returns void
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_kind not in ('title', 'name_style', 'frame', 'hat', 'pattern') then raise exception 'bad kind'; end if;
  if p_code is not null then
    select s.* into it from shop_items s
    where s.code = p_code and s.kind = p_kind
      and ((s.tutor_only and is_tutor())
           or exists (select 1 from user_items u where u.item_id = s.id and u.user_id = auth.uid()));
    if not found then raise exception 'you do not own this'; end if;
  end if;
  if p_kind = 'title' then update profiles set title = it.data->>'text' where id = auth.uid();
  elsif p_kind = 'name_style' then update profiles set name_style = p_code where id = auth.uid();
  elsif p_kind = 'frame' then update profiles set frame = p_code where id = auth.uid();
  elsif p_kind = 'hat' then update profiles set blocky = blocky || jsonb_build_object('hat', coalesce(p_code, 'none')) where id = auth.uid();
  elsif p_kind = 'pattern' then update profiles set blocky = blocky || jsonb_build_object('pattern', coalesce(p_code, 'none')) where id = auth.uid();
  end if;
end $$;


-- ===== 0008_social_exams.sql =====
-- Friends, parties, chat, battle levels, tutor-run exams (windows, attempt limits, focus tracking),
-- and two new avatar slots (face accessory, back item) for the shop.

-- ================================================================ friends
create table if not exists friendships (
  requester uuid not null references profiles(id) on delete cascade,
  addressee uuid not null references profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'accepted')),
  created_at timestamptz not null default now(),
  primary key (requester, addressee),
  check (requester <> addressee)
);
alter table friendships enable row level security;
drop policy if exists fr_select on friendships;
create policy fr_select on friendships for select using (auth.uid() in (requester, addressee) or is_tutor());
grant select on friendships to authenticated;
grant all on friendships to service_role;

create or replace function are_friends(a uuid, b uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from friendships where status = 'accepted' and ((requester = a and addressee = b) or (requester = b and addressee = a)));
$$;

create or replace function send_friend_request(p_user uuid) returns text
language plpgsql security definer set search_path = public as $$
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_user = auth.uid() then raise exception 'that is you'; end if;
  if not exists (select 1 from profiles where id = p_user and status = 'approved') then raise exception 'player not found'; end if;
  if are_friends(auth.uid(), p_user) then return 'already friends'; end if;
  -- they already asked you: accept instead
  if exists (select 1 from friendships where requester = p_user and addressee = auth.uid()) then
    update friendships set status = 'accepted' where requester = p_user and addressee = auth.uid();
    perform notify(p_user, (select display_name from profiles where id = auth.uid()) || ' accepted your friend request', null, '/friends');
    return 'accepted';
  end if;
  insert into friendships(requester, addressee) values (auth.uid(), p_user) on conflict do nothing;
  perform notify(p_user, (select display_name from profiles where id = auth.uid()) || ' sent you a friend request', null, '/friends');
  return 'sent';
end $$;

create or replace function respond_friend_request(p_user uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_accept then
    update friendships set status = 'accepted' where requester = p_user and addressee = auth.uid() and status = 'pending';
    if found then perform notify(p_user, (select display_name from profiles where id = auth.uid()) || ' accepted your friend request', null, '/friends'); end if;
  else
    delete from friendships where requester = p_user and addressee = auth.uid() and status = 'pending';
  end if;
end $$;

create or replace function remove_friend(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from friendships where (requester = auth.uid() and addressee = p_user) or (requester = p_user and addressee = auth.uid());
end $$;

-- everyone approved, as public-safe cards (for finding friends)
create or replace function student_directory() returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, tier tier, name_style text, frame text, role user_role)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp), p.tier, p.name_style, p.frame, p.role
  from profiles p where p.status = 'approved' and is_approved() order by p.display_name;
$$;

-- ================================================================ parties (up to 4, leader takes everyone into battles)
create table if not exists parties (
  id uuid primary key default gen_random_uuid(),
  leader_id uuid not null unique references profiles(id) on delete cascade,
  battle_code text,
  created_at timestamptz not null default now()
);
create table if not exists party_members (
  party_id uuid not null references parties(id) on delete cascade,
  user_id uuid not null unique references profiles(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (party_id, user_id)
);
create table if not exists party_invites (
  party_id uuid not null references parties(id) on delete cascade,
  to_id uuid not null references profiles(id) on delete cascade,
  from_id uuid not null references profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (party_id, to_id)
);
alter table parties enable row level security;
alter table party_members enable row level security;
alter table party_invites enable row level security;

create or replace function my_party() returns uuid language sql stable security definer set search_path = public as $$
  select party_id from party_members where user_id = auth.uid();
$$;
drop policy if exists party_select on parties;
create policy party_select on parties for select using (id = my_party() or is_tutor()
  or exists (select 1 from party_invites i where i.party_id = parties.id and i.to_id = auth.uid()));
drop policy if exists pm_select on party_members;
create policy pm_select on party_members for select using (party_id = my_party() or is_tutor()
  or exists (select 1 from party_invites i where i.party_id = party_members.party_id and i.to_id = auth.uid()));
drop policy if exists pi_select on party_invites;
create policy pi_select on party_invites for select using (to_id = auth.uid() or from_id = auth.uid() or party_id = my_party() or is_tutor());
grant select on parties, party_members, party_invites to authenticated;
grant all on parties, party_members, party_invites to service_role;

create or replace function party_invite(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare pid uuid;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if not are_friends(auth.uid(), p_user) then raise exception 'you can only invite friends'; end if;
  pid := my_party();
  if pid is null then
    insert into parties(leader_id) values (auth.uid()) returning id into pid;
    insert into party_members(party_id, user_id) values (pid, auth.uid());
  elsif (select leader_id from parties where id = pid) <> auth.uid() then
    raise exception 'only the party leader can invite';
  end if;
  if (select count(*) from party_members where party_id = pid) >= 4 then raise exception 'party is full (4 max)'; end if;
  if exists (select 1 from party_members where party_id = pid and user_id = p_user) then raise exception 'already in your party'; end if;
  insert into party_invites(party_id, to_id, from_id) values (pid, p_user, auth.uid()) on conflict do nothing;
  perform notify(p_user, (select display_name from profiles where id = auth.uid()) || ' invited you to their party', 'Join so you go into battles together.', '/friends');
end $$;

create or replace function party_leave() returns void
language plpgsql security definer set search_path = public as $$
declare pid uuid := my_party();
begin
  if pid is null then return; end if;
  if (select leader_id from parties where id = pid) = auth.uid() then
    delete from parties where id = pid;      -- leader leaving disbands the party
  else
    delete from party_members where party_id = pid and user_id = auth.uid();
  end if;
end $$;

create or replace function party_accept(p_party uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from party_invites where party_id = p_party and to_id = auth.uid()) then raise exception 'invite not found'; end if;
  if (select count(*) from party_members where party_id = p_party) >= 4 then raise exception 'party is full'; end if;
  perform party_leave();
  insert into party_members(party_id, user_id) values (p_party, auth.uid());
  delete from party_invites where to_id = auth.uid();
end $$;

create or replace function party_decline(p_party uuid) returns void
language sql security definer set search_path = public as $$
  delete from party_invites where party_id = p_party and to_id = auth.uid();
$$;

create or replace function party_kick(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare pid uuid := my_party();
begin
  if pid is null or (select leader_id from parties where id = pid) <> auth.uid() then raise exception 'only the leader can remove people'; end if;
  if p_user = auth.uid() then raise exception 'use leave instead'; end if;
  delete from party_members where party_id = pid and user_id = p_user;
end $$;

-- ================================================================ battles: a level, and parties follow their leader in
alter table battles add column if not exists tier tier;

-- puts the caller's party (if they lead one) into battle b, filling the given team first, then the other
create or replace function bring_party(b uuid, p_team int) returns void
language plpgsql security definer set search_path = public as $$
declare bt battles%rowtype; cap int; m record; t int; pid uuid;
begin
  select * into bt from battles where id = b;
  select id into pid from parties where leader_id = auth.uid();
  if pid is null then return; end if;
  cap := case bt.mode when '1v1' then 1 else 2 end;
  update parties set battle_code = bt.code where id = pid;
  for m in select user_id from party_members where party_id = pid and user_id <> auth.uid() order by joined_at loop
    if exists (select 1 from battle_players where battle_id = b and user_id = m.user_id) then continue; end if;
    t := case when (select count(*) from battle_players where battle_id = b and team = p_team) < cap then p_team
              when (select count(*) from battle_players where battle_id = b and team = 3 - p_team) < cap then 3 - p_team
              else null end;
    exit when t is null;
    insert into battle_players(battle_id, user_id, team) values (b, m.user_id, t);
    perform notify(m.user_id, 'Your party leader started a battle', 'Battle code ' || bt.code, '/battles/' || bt.code);
  end loop;
end $$;
revoke execute on function bring_party(uuid, int) from public, anon, authenticated;

drop function if exists create_battle(text, uuid, int);
create or replace function create_battle(p_mode text, p_course uuid default null, p_rounds int default 5, p_tier tier default null)
returns text language plpgsql security definer set search_path = public as $$
declare c text; b uuid; lvl tier;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_mode not in ('1v1','2v2') then raise exception 'bad mode'; end if;
  lvl := coalesce((select tier from courses where id = p_course), p_tier, (select tier from profiles where id = auth.uid()));
  loop
    c := upper(substr(md5(random()::text), 1, 5));
    exit when not exists (select 1 from battles where code = c);
  end loop;
  insert into battles(code, mode, course_id, host_id, round_count, tier)
  values (c, p_mode, p_course, auth.uid(), least(greatest(coalesce(p_rounds, 5), 3), 10), lvl)
  returning id into b;
  insert into battle_players(battle_id, user_id, team) values (b, auth.uid(), 1);
  perform bring_party(b, 1);
  return c;
end $$;

create or replace function join_battle(p_code text, p_team int default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; cap int; t int; n1 int; n2 int;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into b from battles where code = upper(p_code) for update;
  if not found then raise exception 'battle not found'; end if;
  if exists(select 1 from battle_players where battle_id = b.id and user_id = auth.uid()) then
    if b.status = 'lobby' and p_team in (1,2) then
      cap := case b.mode when '1v1' then 1 else 2 end;
      if (select count(*) from battle_players where battle_id = b.id and team = p_team and user_id <> auth.uid()) < cap then
        update battle_players set team = p_team where battle_id = b.id and user_id = auth.uid();
      end if;
    end if;
    return b.id;
  end if;
  if b.status <> 'lobby' then raise exception 'battle already started'; end if;
  cap := case b.mode when '1v1' then 1 else 2 end;
  select count(*) filter (where team = 1), count(*) filter (where team = 2) into n1, n2
  from battle_players where battle_id = b.id;
  t := coalesce(p_team, case when n1 <= n2 then 1 else 2 end);
  if (t = 1 and n1 >= cap) then t := 2; end if;
  if (t = 2 and n2 >= cap) then t := 1; end if;
  if (t = 1 and n1 >= cap) or (t = 2 and n2 >= cap) then raise exception 'battle is full'; end if;
  insert into battle_players(battle_id, user_id, team) values (b.id, auth.uid(), t);
  perform bring_party(b.id, t);
  return b.id;
end $$;

create or replace function start_battle(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; i int := 0; q uuid;
begin
  select * into b from battles where id = p_battle for update;
  if b.host_id <> auth.uid() then raise exception 'only the host can start'; end if;
  if b.status <> 'lobby' then raise exception 'already started'; end if;
  if (select count(distinct team) from battle_players where battle_id = b.id) < 2 then
    raise exception 'both teams need at least one player';
  end if;
  for q in
    select qq.id from questions qq join question_keys k on k.question_id = qq.id join courses cc on cc.id = qq.course_id
    where qq.battle_ok
      and (case when b.course_id is not null then qq.course_id = b.course_id
                when b.tier is not null then cc.tier = b.tier else true end)
    order by random() limit b.round_count
  loop
    i := i + 1;
    insert into battle_rounds(battle_id, round_no, question_id) values (b.id, i, q);
  end loop;
  if i = 0 then raise exception 'no questions available for this level yet'; end if;
  update battles set status = 'live', round_count = i, current_round = 1, phase = 'question',
    phase_started_at = now() where id = b.id;
end $$;

-- ================================================================ chat (with battle requests)
create table if not exists chat_messages (
  id bigserial primary key,
  user_id uuid not null references profiles(id) on delete cascade,
  body text not null check (char_length(body) between 1 and 500),
  kind text not null default 'text' check (kind in ('text', 'battle')),
  battle_code text,
  mode text,
  tier tier,
  course_title text,
  deleted boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists chat_recent on chat_messages(created_at desc);
alter table chat_messages enable row level security;
drop policy if exists chat_select on chat_messages;
create policy chat_select on chat_messages for select using (is_approved() and (not deleted or is_tutor()));
grant select on chat_messages to authenticated;
grant all on chat_messages to service_role;

create or replace function post_chat(p_body text, p_battle_code text default null) returns bigint
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; mid bigint; body text := btrim(coalesce(p_body, ''));
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if (select count(*) from chat_messages where user_id = auth.uid() and created_at > now() - interval '30 seconds') >= 6 then
    raise exception 'slow down a bit';
  end if;
  if p_battle_code is not null then
    select * into b from battles where code = upper(p_battle_code);
    if not found or b.status <> 'lobby' then raise exception 'that battle is not open'; end if;
    insert into chat_messages(user_id, body, kind, battle_code, mode, tier, course_title)
    values (auth.uid(), coalesce(nullif(body, ''), 'Join my battle!'), 'battle', b.code, b.mode, b.tier,
            (select title from courses where id = b.course_id))
    returning id into mid;
  else
    if body = '' then raise exception 'empty message'; end if;
    insert into chat_messages(user_id, body) values (auth.uid(), left(body, 500)) returning id into mid;
  end if;
  return mid;
end $$;

create or replace function delete_chat(p_id bigint) returns void
language plpgsql security definer set search_path = public as $$
begin
  update chat_messages set deleted = true where id = p_id and (user_id = auth.uid() or is_tutor());
end $$;

-- ================================================================ exams run by the tutor
alter table quizzes add column if not exists closes_at timestamptz;
alter table quizzes add column if not exists max_attempts int;
alter table quiz_attempts add column if not exists focus_lost int not null default 0;

-- One time only: practice tests start locked so the tutor decides when exams open.
create table if not exists app_flags (key text primary key, set_at timestamptz not null default now());
alter table app_flags enable row level security;
do $$ begin
  if not exists (select 1 from app_flags where key = 'exams_locked_v1') then
    update quizzes set status = 'locked' where kind = 'exam' and status = 'published';
    insert into app_flags(key) values ('exams_locked_v1');
  end if;
end $$;

create or replace function start_quiz(p_quiz uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  qz quizzes%rowtype;
  ids uuid[];
  att uuid;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into qz from quizzes where id = p_quiz;
  if not found or not (is_live(qz.status, qz.release_at) or is_tutor()) then
    raise exception 'quiz locked';
  end if;
  if qz.closes_at is not null and now() > qz.closes_at and not is_tutor() then raise exception 'exam closed'; end if;
  if qz.max_attempts is not null and not is_tutor() and
     (select count(*) from quiz_attempts where user_id = auth.uid() and quiz_id = qz.id) >= qz.max_attempts then
    raise exception 'no attempts left';
  end if;
  if qz.chapter_id is not null and not is_tutor() and not exists (
      select 1 from chapters c where c.id = qz.chapter_id and is_live(c.status, c.release_at)) then
    raise exception 'chapter locked';
  end if;

  if qz.kind = 'speedrun' then
    select array_agg(id) into ids from (
      select q.id from questions q join question_keys k on k.question_id = q.id
      where (q.quiz_id = qz.id) or (qz.chapter_id is null and q.course_id = qz.course_id and q.battle_ok)
      order by random() limit 10) s;
  elsif qz.kind = 'exam' then
    select array_agg(id) into ids from (
      select q.id from questions q
      join question_keys k on k.question_id = q.id
      join chapters c on c.id = q.chapter_id
      where q.course_id = qz.course_id and (is_live(c.status, c.release_at) or is_tutor())
      order by random() limit coalesce(qz.question_count, 40)) s;
  elsif qz.kind = 'review' then
    select array_agg(question_id) into ids from (
      select r.question_id from review_items r join question_keys k on k.question_id = r.question_id
      where r.user_id = auth.uid() and r.course_id = qz.course_id and r.due_at <= now()
      order by r.due_at limit 10) s;
    if ids is null then raise exception 'nothing to review'; end if;
  else
    select array_agg(id) into ids from (
      select q.id from questions q join question_keys k on k.question_id = q.id
      where q.quiz_id = qz.id order by random()) s;
  end if;
  if ids is null then raise exception 'quiz has no questions yet'; end if;

  insert into quiz_attempts(user_id, quiz_id, question_ids) values (auth.uid(), qz.id, ids)
  returning id into att;

  return jsonb_build_object(
    'attempt_id', att, 'kind', qz.kind, 'title', qz.title, 'time_limit_sec', qz.time_limit_sec,
    'questions', (select jsonb_agg(jsonb_build_object('id', q.id, 'prompt', q.prompt, 'options', q.options)
                   order by array_position(ids, q.id))
                  from questions q where q.id = any(ids)));
end $$;

-- submit_quiz gains a count of how often the student left the exam screen (shown to the tutor)
drop function if exists submit_quiz(uuid, jsonb);
create or replace function submit_quiz(p_attempt uuid, p_answers jsonb, p_focus_lost int default 0) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  att quiz_attempts%rowtype;
  qz quizzes%rowtype;
  crs courses%rowtype;
  n int;
  correct_n int := 0;
  elapsed int;
  pts int := 0;
  frac numeric;
  prev numeric;
  xp_base int := 0;
  res jsonb;
  results jsonb;
  is_flagged boolean := false;
  passed_today boolean;
  runs_today int;
  r record;
  added int := 0;
  mastered int := 0;
begin
  select * into att from quiz_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.finished_at is not null then raise exception 'already submitted'; end if;
  select * into qz from quizzes where id = att.quiz_id;
  select * into crs from courses where id = qz.course_id;

  n := array_length(att.question_ids, 1);
  elapsed := (extract(epoch from (now() - att.started_at)) * 1000)::int;

  select count(*) into correct_n
  from unnest(att.question_ids) qid join question_keys k on k.question_id = qid
  where (p_answers->>(qid::text)) is not null and (p_answers->>(qid::text))::int = k.correct;

  select jsonb_agg(jsonb_build_object(
      'id', q.id, 'choice', (p_answers->>(q.id::text))::int, 'correct', k.correct,
      'right', coalesce((p_answers->>(q.id::text))::int = k.correct, false), 'explanation', q.explanation)
      order by array_position(att.question_ids, q.id))
  into results
  from questions q join question_keys k on k.question_id = q.id where q.id = any(att.question_ids);

  -- anti-cheat: nobody genuinely answers faster than ~1.2 s per question; overtime also flags
  if elapsed < 1200 * n then is_flagged := true; end if;
  if qz.time_limit_sec is not null and elapsed > (qz.time_limit_sec + 15) * 1000 then is_flagged := true; end if;

  frac := correct_n::numeric / n;
  pts := correct_n * 100 + floor(greatest(0, n * 15000 - elapsed) / 1000.0 * 10 * frac)::int;

  if not is_flagged then
    if qz.kind = 'quiz' then
      -- only the improvement on your best score pays, so retakes can't farm XP
      select coalesce(max(score::numeric / nullif(total, 0)), 0) into prev
      from quiz_attempts where user_id = att.user_id and quiz_id = qz.id and finished_at is not null and not flagged;
      xp_base := round(qz.xp_reward * greatest(0, frac - prev));
    elsif qz.kind = 'review' then
      -- 5 XP per mistake fixed; items only come back on a schedule, so this can't be farmed
      xp_base := correct_n * 5;
    else
      -- speedrun: first 3 runs a day pay; exam: first 2 a day pay
      select count(*) into runs_today from quiz_attempts
      where user_id = att.user_id and quiz_id = qz.id and finished_at is not null and not flagged
        and (finished_at at time zone 'Indian/Mauritius')::date = today_local();
      if runs_today < (case when qz.kind = 'exam' then 2 else 3 end) then xp_base := round(qz.xp_reward * frac); end if;
    end if;

    -- mistakes deck
    for r in
      select qid, (p_answers->>(qid::text)) is not null and (p_answers->>(qid::text))::int = k.correct as ok
      from unnest(att.question_ids) qid join question_keys k on k.question_id = qid
    loop
      if not r.ok then
        insert into review_items(user_id, question_id, course_id, box, due_at)
        values (att.user_id, r.qid, qz.course_id, 0, now() + interval '1 day')
        on conflict (user_id, question_id) do update
          set box = 0, due_at = now() + interval '1 day', times_wrong = review_items.times_wrong + 1, updated_at = now();
        added := added + 1;
      elsif qz.kind = 'review' then
        update review_items set box = box + 1, updated_at = now(),
          due_at = now() + case box when 0 then interval '3 days' else interval '7 days' end
        where user_id = att.user_id and question_id = r.qid;
        delete from review_items where user_id = att.user_id and question_id = r.qid and box >= 3;
        if found then mastered := mastered + 1; end if;
      end if;
    end loop;
  end if;

  select exists(select 1 from quiz_attempts where user_id = att.user_id and quiz_id = qz.id
      and finished_at is not null and not flagged and score * 2 >= total
      and (finished_at at time zone 'Indian/Mauritius')::date = today_local()) into passed_today;

  update quiz_attempts set finished_at = now(), score = correct_n, total = n, time_ms = elapsed,
    points = pts, flagged = is_flagged, answers = p_answers, focus_lost = greatest(0, least(coalesce(p_focus_lost, 0), 999))
  where id = att.id;

  res := award_xp(att.user_id, xp_base, 'quiz', qz.id::text, crs.tier, case when xp_base > 0 then 5 else 0 end, true);
  update quiz_attempts set xp_awarded = coalesce((res->>'xp')::int, 0) where id = att.id;

  if not is_flagged and frac >= 0.5 and not passed_today then
    perform bump_challenge(att.user_id, 'quiz_pass', 1, null);
    perform bump_challenge(att.user_id, 'quiz_specific', 1, qz.id);
  end if;
  perform check_achievements(att.user_id);

  return jsonb_build_object('score', correct_n, 'total', n, 'points', pts, 'time_ms', elapsed,
    'flagged', is_flagged, 'xp', coalesce((res->>'xp')::int, 0), 'multiplier', res->'multiplier',
    'leveled_up', coalesce((res->>'leveled_up')::boolean, false), 'level_after', res->'level_after',
    'review_added', added, 'review_mastered', mastered, 'results', results);
end $$;

-- ================================================================ new avatar slots for shop items
alter table shop_items drop constraint if exists shop_items_kind_check;
alter table shop_items add constraint shop_items_kind_check check (kind in ('title', 'name_style', 'frame', 'hat', 'pattern', 'streak_freeze', 'face_acc', 'back'));

create or replace function equip_item(p_kind text, p_code text) returns void
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_kind not in ('title', 'name_style', 'frame', 'hat', 'pattern', 'face_acc', 'back') then raise exception 'bad kind'; end if;
  if p_code is not null then
    select s.* into it from shop_items s
    where s.code = p_code and s.kind = p_kind
      and ((s.tutor_only and is_tutor())
           or exists (select 1 from user_items u where u.item_id = s.id and u.user_id = auth.uid()));
    if not found then raise exception 'you do not own this'; end if;
  end if;
  if p_kind = 'title' then update profiles set title = it.data->>'text' where id = auth.uid();
  elsif p_kind = 'name_style' then update profiles set name_style = p_code where id = auth.uid();
  elsif p_kind = 'frame' then update profiles set frame = p_code where id = auth.uid();
  else update profiles set blocky = blocky || jsonb_build_object(p_kind, coalesce(p_code, 'none')) where id = auth.uid();
  end if;
end $$;

-- ================================================================ realtime for the new live features
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['chat_messages', 'friendships', 'parties', 'party_members', 'party_invites'] loop
      begin
        execute format('alter publication supabase_realtime add table %I', t);
      exception when duplicate_object then null;
      end;
    end loop;
  end if;
end $$;


-- ===== 0009_subjects.sql =====
-- Each student picks the subjects they take (e.g. {economics, business}). NULL = not chosen yet.
alter table profiles add column if not exists subjects text[];

-- 'as-economics' -> 'economics', 'o-accounting' -> 'accounting'
create or replace function subject_of(slug text) returns text language sql immutable as $$
  select regexp_replace(slug, '^(o|as|a)-', '');
$$;

-- Students save their own subjects. Only subjects that exist for their level are accepted.
create or replace function set_my_subjects(p_subjects text[]) returns text[]
language plpgsql security definer set search_path = public as $$
declare me profiles%rowtype; clean text[];
begin
  select * into me from profiles where id = auth.uid();
  if not found or me.status <> 'approved' then raise exception 'not approved'; end if;
  select array_agg(distinct s order by s) into clean
  from unnest(coalesce(p_subjects, '{}')) s
  where exists (select 1 from courses c where c.active and subject_of(c.slug) = s
                and (case when me.tier = 'O' then c.tier = 'O' else c.tier in ('AS', 'A') end));
  if clean is null or array_length(clean, 1) = 0 then raise exception 'pick at least one subject'; end if;
  update profiles set subjects = clean where id = me.id;
  return clean;
end $$;
revoke all on function set_my_subjects(text[]) from public, anon;
grant execute on function set_my_subjects(text[]) to authenticated;


-- ===== 0010_battle_levels.sql =====
-- Battles can mix AS + A Level, and a mixed battle can be limited to one subject (e.g. AS + A Economics).
alter table battles add column if not exists subject text;
alter table battles add column if not exists both_levels boolean not null default false;

drop function if exists create_battle(text, uuid, int, tier);
create or replace function create_battle(p_mode text, p_course uuid default null, p_rounds int default 5, p_tier tier default null,
                                         p_subject text default null, p_both boolean default false)
returns text language plpgsql security definer set search_path = public as $$
declare c text; b uuid; lvl tier; subj text := nullif(btrim(coalesce(p_subject, '')), ''); both_lv boolean := coalesce(p_both, false);
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_mode not in ('1v1','2v2') then raise exception 'bad mode'; end if;
  if p_course is not null then
    subj := null; both_lv := false;
    select tier into lvl from courses where id = p_course;
  else
    lvl := case when both_lv then 'A'::tier else coalesce(p_tier, (select tier from profiles where id = auth.uid())) end;
    if lvl = 'O' then both_lv := false; end if;
    if subj is not null and not exists (
        select 1 from courses cc where cc.active and subject_of(cc.slug) = subj
          and (cc.tier = lvl or (both_lv and cc.tier = 'AS'))) then
      raise exception 'no such subject at that level';
    end if;
  end if;
  loop
    c := upper(substr(md5(random()::text), 1, 5));
    exit when not exists (select 1 from battles where code = c);
  end loop;
  insert into battles(code, mode, course_id, host_id, round_count, tier, subject, both_levels)
  values (c, p_mode, p_course, auth.uid(), least(greatest(coalesce(p_rounds, 5), 3), 10), lvl, subj, both_lv)
  returning id into b;
  insert into battle_players(battle_id, user_id, team) values (b, auth.uid(), 1);
  perform bring_party(b, 1);
  return c;
end $$;
revoke all on function create_battle(text, uuid, int, tier, text, boolean) from public, anon;
grant execute on function create_battle(text, uuid, int, tier, text, boolean) to authenticated;

create or replace function start_battle(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; i int := 0; q uuid;
begin
  select * into b from battles where id = p_battle for update;
  if b.host_id <> auth.uid() then raise exception 'only the host can start'; end if;
  if b.status <> 'lobby' then raise exception 'already started'; end if;
  if (select count(distinct team) from battle_players where battle_id = b.id) < 2 then
    raise exception 'both teams need at least one player';
  end if;
  for q in
    select qq.id from questions qq join question_keys k on k.question_id = qq.id join courses cc on cc.id = qq.course_id
    where qq.battle_ok
      and (case when b.course_id is not null then qq.course_id = b.course_id
                else (b.tier is null or cc.tier = b.tier or (b.both_levels and cc.tier = 'AS'))
                     and (b.subject is null or subject_of(cc.slug) = b.subject) end)
    order by random() limit b.round_count
  loop
    i := i + 1;
    insert into battle_rounds(battle_id, round_no, question_id) values (b.id, i, q);
  end loop;
  if i = 0 then raise exception 'no questions available for this level yet'; end if;
  update battles set status = 'live', round_count = i, current_round = 1, phase = 'question',
    phase_started_at = now() where id = b.id;
end $$;

-- chat battle requests describe mixed battles properly ("AS + A Level · Economics")
create or replace function post_chat(p_body text, p_battle_code text default null) returns bigint
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; mid bigint; body text := btrim(coalesce(p_body, ''));
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if (select count(*) from chat_messages where user_id = auth.uid() and created_at > now() - interval '30 seconds') >= 6 then
    raise exception 'slow down a bit';
  end if;
  if p_battle_code is not null then
    select * into b from battles where code = upper(p_battle_code);
    if not found or b.status <> 'lobby' then raise exception 'that battle is not open'; end if;
    insert into chat_messages(user_id, body, kind, battle_code, mode, tier, course_title)
    values (auth.uid(), coalesce(nullif(body, ''), 'Join my battle!'), 'battle', b.code, b.mode, b.tier,
            coalesce((select title from courses where id = b.course_id),
                     case when b.both_levels then 'AS + A Level ' else '' end || coalesce(initcap(replace(b.subject, '-', ' ')), 'Mixed')))
    returning id into mid;
  else
    if body = '' then raise exception 'empty message'; end if;
    insert into chat_messages(user_id, body) values (auth.uid(), left(body, 500)) returning id into mid;
  end if;
  return mid;
end $$;


-- ===== 0011_tutorial.sql =====
-- Site tour. Everyone with tutorial_version below the site's version sees it (new students start at 0).
-- The tutor can bump the site version to show it to everyone again.
create table if not exists site_settings (
  id int primary key default 1 check (id = 1),
  tutorial_version int not null default 1,
  tutorial_launched_at timestamptz
);
insert into site_settings(id) values (1) on conflict (id) do nothing;
alter table site_settings enable row level security;
drop policy if exists site_settings_select on site_settings;
create policy site_settings_select on site_settings for select using (is_approved());
grant select on site_settings to authenticated;
grant all on site_settings to service_role;

-- existing accounts start as "seen" so the tutor decides when they get it; new sign-ups start at 0 and see it
do $$ begin
  if not exists (select 1 from information_schema.columns where table_name = 'profiles' and column_name = 'tutorial_version') then
    alter table profiles add column tutorial_version int not null default 0;
    update profiles set tutorial_version = 1;
  end if;
end $$;

-- student finished (or skipped) the tour
create or replace function finish_tutorial() returns void
language plpgsql security definer set search_path = public as $$
begin
  update profiles set tutorial_version = (select tutorial_version from site_settings where id = 1) where id = auth.uid();
end $$;

-- tutor: show the tour to everyone again
create or replace function relaunch_tutorial() returns int
language plpgsql security definer set search_path = public as $$
declare v int;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  update site_settings set tutorial_version = tutorial_version + 1, tutorial_launched_at = now() where id = 1 returning tutorial_version into v;
  update profiles set tutorial_version = v where id = auth.uid(); -- the tutor isn't shown it
  return v;
end $$;

revoke all on function finish_tutorial() from public, anon;
revoke all on function relaunch_tutorial() from public, anon;
grant execute on function finish_tutorial() to authenticated;
grant execute on function relaunch_tutorial() to authenticated;

-- live: students who are already on the site get the tour as soon as the tutor launches it
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin execute 'alter publication supabase_realtime add table site_settings';
    exception when duplicate_object then null; end;
  end if;
end $$;


-- ===== 0012_polls.sql =====
-- Live polls: the tutor posts a question, it pops up for every student online, results update live.
create table if not exists polls (
  id uuid primary key default gen_random_uuid(),
  question text not null check (char_length(question) between 2 and 300),
  options jsonb not null,                       -- ["Yes", "No", ...]
  counts int[] not null,                        -- live tally, one per option (kept by vote_poll)
  correct int,                                  -- optional: shown once the poll is closed
  status text not null default 'open' check (status in ('open', 'closed')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  closed_at timestamptz
);
create table if not exists poll_votes (
  poll_id uuid not null references polls(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  choice int not null,
  voted_at timestamptz not null default now(),
  primary key (poll_id, user_id)
);
alter table polls enable row level security;
alter table poll_votes enable row level security;
drop policy if exists polls_select on polls;
create policy polls_select on polls for select using (is_approved());
drop policy if exists poll_votes_select on poll_votes;
create policy poll_votes_select on poll_votes for select using (user_id = auth.uid() or is_tutor());
grant select on polls, poll_votes to authenticated;
grant all on polls, poll_votes to service_role;

create or replace function create_poll(p_question text, p_options text[], p_correct int default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare opts text[]; id uuid; n int;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  select array_agg(left(btrim(o), 120)) into opts from unnest(p_options) o where btrim(o) <> '';
  n := coalesce(array_length(opts, 1), 0);
  if n < 2 or n > 6 then raise exception 'a poll needs 2 to 6 options'; end if;
  if p_correct is not null and (p_correct < 0 or p_correct >= n) then raise exception 'bad correct option'; end if;
  update polls set status = 'closed', closed_at = now() where status = 'open'; -- one live poll at a time
  insert into polls(question, options, counts, correct, created_by)
  values (left(btrim(p_question), 300), to_jsonb(opts), array_fill(0, array[n]), p_correct, auth.uid())
  returning polls.id into id;
  return id;
end $$;

create or replace function vote_poll(p_poll uuid, p_choice int) returns void
language plpgsql security definer set search_path = public as $$
declare pl polls%rowtype; prev int;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into pl from polls where id = p_poll for update;
  if not found or pl.status <> 'open' then raise exception 'this poll is closed'; end if;
  if p_choice < 0 or p_choice >= array_length(pl.counts, 1) then raise exception 'bad option'; end if;
  select choice into prev from poll_votes where poll_id = p_poll and user_id = auth.uid();
  if prev = p_choice then return; end if;
  if prev is not null then pl.counts[prev + 1] := greatest(0, pl.counts[prev + 1] - 1); end if;
  pl.counts[p_choice + 1] := pl.counts[p_choice + 1] + 1;
  insert into poll_votes(poll_id, user_id, choice) values (p_poll, auth.uid(), p_choice)
  on conflict (poll_id, user_id) do update set choice = excluded.choice, voted_at = now();
  update polls set counts = pl.counts where id = p_poll;
end $$;

create or replace function close_poll(p_poll uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  update polls set status = 'closed', closed_at = now() where id = p_poll and status = 'open';
end $$;

revoke all on function create_poll(text, text[], int) from public, anon;
revoke all on function vote_poll(uuid, int) from public, anon;
revoke all on function close_poll(uuid) from public, anon;
grant execute on function create_poll(text, text[], int) to authenticated;
grant execute on function vote_poll(uuid, int) to authenticated;
grant execute on function close_poll(uuid) to authenticated;

do $$ declare t text; begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['polls', 'poll_votes'] loop
      begin execute format('alter publication supabase_realtime add table %I', t);
      exception when duplicate_object then null; end;
    end loop;
  end if;
end $$;


-- ===== 0013_battle_chapter.sql =====
-- Battles can be limited to one chapter of a course (e.g. O Level CS · 4 Software).
alter table battles add column if not exists chapter_id uuid references chapters(id) on delete set null;

drop function if exists create_battle(text, uuid, int, tier, text, boolean);
create or replace function create_battle(p_mode text, p_course uuid default null, p_rounds int default 5, p_tier tier default null,
                                         p_subject text default null, p_both boolean default false, p_chapter uuid default null)
returns text language plpgsql security definer set search_path = public as $$
declare c text; b uuid; lvl tier; subj text := nullif(btrim(coalesce(p_subject, '')), ''); both_lv boolean := coalesce(p_both, false);
        crs uuid := p_course;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_mode not in ('1v1','2v2') then raise exception 'bad mode'; end if;
  if p_chapter is not null then
    select course_id into crs from chapters where id = p_chapter;
    if crs is null then raise exception 'chapter not found'; end if;
  end if;
  if crs is not null then
    subj := null; both_lv := false;
    select tier into lvl from courses where id = crs;
  else
    lvl := case when both_lv then 'A'::tier else coalesce(p_tier, (select tier from profiles where id = auth.uid())) end;
    if lvl = 'O' then both_lv := false; end if;
    if subj is not null and not exists (
        select 1 from courses cc where cc.active and subject_of(cc.slug) = subj
          and (cc.tier = lvl or (both_lv and cc.tier = 'AS'))) then
      raise exception 'no such subject at that level';
    end if;
  end if;
  loop
    c := upper(substr(md5(random()::text), 1, 5));
    exit when not exists (select 1 from battles where code = c);
  end loop;
  insert into battles(code, mode, course_id, chapter_id, host_id, round_count, tier, subject, both_levels)
  values (c, p_mode, crs, p_chapter, auth.uid(), least(greatest(coalesce(p_rounds, 5), 3), 10), lvl, subj, both_lv)
  returning id into b;
  insert into battle_players(battle_id, user_id, team) values (b, auth.uid(), 1);
  perform bring_party(b, 1);
  return c;
end $$;
revoke all on function create_battle(text, uuid, int, tier, text, boolean, uuid) from public, anon;
grant execute on function create_battle(text, uuid, int, tier, text, boolean, uuid) to authenticated;

create or replace function start_battle(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; i int := 0; q uuid;
begin
  select * into b from battles where id = p_battle for update;
  if b.host_id <> auth.uid() then raise exception 'only the host can start'; end if;
  if b.status <> 'lobby' then raise exception 'already started'; end if;
  if (select count(distinct team) from battle_players where battle_id = b.id) < 2 then
    raise exception 'both teams need at least one player';
  end if;
  for q in
    select qq.id from questions qq join question_keys k on k.question_id = qq.id join courses cc on cc.id = qq.course_id
    where qq.battle_ok
      and (case when b.chapter_id is not null then qq.chapter_id = b.chapter_id
                when b.course_id is not null then qq.course_id = b.course_id
                else (b.tier is null or cc.tier = b.tier or (b.both_levels and cc.tier = 'AS'))
                     and (b.subject is null or subject_of(cc.slug) = b.subject) end)
    order by random() limit b.round_count
  loop
    i := i + 1;
    insert into battle_rounds(battle_id, round_no, question_id) values (b.id, i, q);
  end loop;
  if i = 0 then raise exception 'no questions available for this level yet'; end if;
  update battles set status = 'live', round_count = i, current_round = 1, phase = 'question',
    phase_started_at = now() where id = b.id;
end $$;


-- ===== 0014_ranked_pressure.sql =====
-- Battle styles: classic, ranked (rating goes up/down), pressure (every answer halves the time left).
alter table battles add column if not exists style text not null default 'classic';
alter table battles drop constraint if exists battles_style_check;
alter table battles add constraint battles_style_check check (style in ('classic', 'ranked', 'pressure'));
alter table battles add column if not exists phase_ends_at timestamptz;      -- pressure: the shortened deadline for this round
alter table battle_players add column if not exists rating_delta int;          -- ranked: rating change from this battle

alter table profiles add column if not exists rating int not null default 1000;
alter table profiles add column if not exists ranked_played int not null default 0;
alter table profiles add column if not exists ranked_wins int not null default 0;

-- ---------------------------------------------------------------- create (adds p_style)
drop function if exists create_battle(text, uuid, int, tier, text, boolean, uuid);
create or replace function create_battle(p_mode text, p_course uuid default null, p_rounds int default 5, p_tier tier default null,
                                         p_subject text default null, p_both boolean default false, p_chapter uuid default null,
                                         p_style text default 'classic')
returns text language plpgsql security definer set search_path = public as $$
declare c text; b uuid; lvl tier; subj text := nullif(btrim(coalesce(p_subject, '')), ''); both_lv boolean := coalesce(p_both, false);
        crs uuid := p_course; chap uuid := p_chapter; sty text := coalesce(p_style, 'classic'); rounds int;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_mode not in ('1v1','2v2') then raise exception 'bad mode'; end if;
  if sty not in ('classic', 'ranked', 'pressure') then raise exception 'bad style'; end if;
  if sty = 'ranked' then chap := null; end if;          -- ranked covers a whole subject or level, not one easy chapter
  rounds := least(greatest(coalesce(p_rounds, 5), 3), 10);
  if sty = 'ranked' then rounds := greatest(rounds, 5); end if;
  if chap is not null then
    select course_id into crs from chapters where id = chap;
    if crs is null then raise exception 'chapter not found'; end if;
  end if;
  if crs is not null then
    subj := null; both_lv := false;
    select tier into lvl from courses where id = crs;
  else
    lvl := case when both_lv then 'A'::tier else coalesce(p_tier, (select tier from profiles where id = auth.uid())) end;
    if lvl = 'O' then both_lv := false; end if;
    if subj is not null and not exists (
        select 1 from courses cc where cc.active and subject_of(cc.slug) = subj
          and (cc.tier = lvl or (both_lv and cc.tier = 'AS'))) then
      raise exception 'no such subject at that level';
    end if;
  end if;
  loop
    c := upper(substr(md5(random()::text), 1, 5));
    exit when not exists (select 1 from battles where code = c);
  end loop;
  insert into battles(code, mode, course_id, chapter_id, host_id, round_count, tier, subject, both_levels, style)
  values (c, p_mode, crs, chap, auth.uid(), rounds, lvl, subj, both_lv, sty)
  returning id into b;
  insert into battle_players(battle_id, user_id, team) values (b, auth.uid(), 1);
  perform bring_party(b, 1);
  return c;
end $$;
revoke all on function create_battle(text, uuid, int, tier, text, boolean, uuid, text) from public, anon;
grant execute on function create_battle(text, uuid, int, tier, text, boolean, uuid, text) to authenticated;

-- ---------------------------------------------------------------- answers: pressure cuts the clock
create or replace function answer_battle(p_battle uuid, p_choice int) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; k int; elapsed int; pts int := 0; ok boolean; deadline timestamptz; left_s numeric;
begin
  select * into b from battles where id = p_battle for update;
  if b.status <> 'live' or b.phase <> 'question' then raise exception 'not accepting answers'; end if;
  if not exists(select 1 from battle_players where battle_id = b.id and user_id = auth.uid()) then
    raise exception 'not in this battle';
  end if;
  deadline := coalesce(b.phase_ends_at, b.phase_started_at + make_interval(secs => b.round_seconds));
  if now() > deadline + interval '1 second' then raise exception 'too late'; end if;
  elapsed := (extract(epoch from (now() - b.phase_started_at)) * 1000)::int;
  select qk.correct into k from battle_rounds r join question_keys qk on qk.question_id = r.question_id
  where r.battle_id = b.id and r.round_no = b.current_round;
  ok := p_choice = k;
  if ok then pts := 100 + greatest(0, round(100 * (1 - elapsed::numeric / (b.round_seconds * 1000))))::int; end if;
  insert into battle_answers(battle_id, round_no, user_id, choice, correct, ms, points)
  values (b.id, b.current_round, auth.uid(), p_choice, ok, elapsed, pts)
  on conflict do nothing;
  if not found then return; end if;
  if (select count(*) from battle_answers where battle_id = b.id and round_no = b.current_round)
     >= (select count(*) from battle_players where battle_id = b.id) then
    perform battle_reveal(b.id);
  elsif b.style = 'pressure' then
    -- everyone else now has half the time that was left (never under 3 seconds)
    left_s := extract(epoch from (deadline - now()));
    if left_s > 3 then
      update battles set phase_ends_at = now() + make_interval(secs => greatest(3, left_s / 2)) where id = b.id;
    end if;
  end if;
end $$;

create or replace function tick_battle(p_battle uuid) returns text
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype;
begin
  select * into b from battles where id = p_battle for update;
  if not found or b.status <> 'live' then return coalesce(b.status, 'missing'); end if;
  if not exists(select 1 from battle_players where battle_id = b.id and user_id = auth.uid()) then
    return b.status;
  end if;
  if b.phase = 'question' and now() > coalesce(b.phase_ends_at, b.phase_started_at + make_interval(secs => b.round_seconds)) + interval '1 second' then
    perform battle_reveal(b.id);
  elsif b.phase = 'reveal' and now() > b.phase_started_at + interval '5 seconds' then
    if b.current_round >= b.round_count then
      perform battle_finish(b.id);
      return 'finished';
    end if;
    update battles set current_round = current_round + 1, phase = 'question', phase_started_at = now(), phase_ends_at = null where id = b.id;
  end if;
  return 'live';
end $$;

-- ---------------------------------------------------------------- finish: XP as before, plus rating for ranked
create or replace function battle_finish(p_battle uuid) returns void
language plpgsql security definer set search_path = public as $$
declare b battles%rowtype; s1 int; s2 int; w int; pl record; c courses%rowtype; played_today int; nplayers int;
        r1 numeric; r2 numeric; e1 numeric; res1 numeric; d int; k int; repeats int;
begin
  select * into b from battles where id = p_battle for update;
  select coalesce(sum(score) filter (where team = 1), 0), coalesce(sum(score) filter (where team = 2), 0), count(*)
    into s1, s2, nplayers from battle_players where battle_id = b.id;
  w := case when s1 > s2 then 1 when s2 > s1 then 2 else 0 end;
  update battles set status = 'finished', winner_team = w where id = b.id;
  if b.rewarded then return; end if;
  update battles set rewarded = true where id = b.id;
  select * into c from courses where id = b.course_id;
  for pl in select * from battle_players where battle_id = b.id loop
    select count(*) into played_today from xp_events
      where user_id = pl.user_id and reason = 'battle' and (created_at at time zone 'Indian/Mauritius')::date = today_local();
    if nplayers >= 2 and played_today < 5 then
      perform award_xp(pl.user_id, case when w = 0 then 35 when w = pl.team then 60 else 20 end,
                       'battle', b.id::text, c.tier, case when w = pl.team then 10 else 3 end, true);
    end if;
    perform bump_challenge(pl.user_id, 'battle_play', 1, null);
    if w = pl.team then perform bump_challenge(pl.user_id, 'battle_win', 1, null); end if;
    perform check_achievements(pl.user_id);
  end loop;

  -- ranked: Elo on team averages. Students only; tutors play unrated.
  if b.style = 'ranked' and exists (select 1 from battle_players where battle_id = b.id and team = 1)
     and exists (select 1 from battle_players where battle_id = b.id and team = 2) then
    select avg(p.rating) filter (where bp.team = 1), avg(p.rating) filter (where bp.team = 2) into r1, r2
    from battle_players bp join profiles p on p.id = bp.user_id where bp.battle_id = b.id;
    e1 := 1 / (1 + power(10, (r2 - r1) / 400));
    res1 := case w when 1 then 1 when 2 then 0 else 0.5 end;
    for pl in select bp.*, p.ranked_played, p.role from battle_players bp join profiles p on p.id = bp.user_id where bp.battle_id = b.id loop
      if pl.role <> 'student' then continue; end if;
      k := case when pl.ranked_played < 10 then 40 else 28 end;           -- placement games move faster
      d := round(k * (case when pl.team = 1 then res1 - e1 else (1 - res1) - (1 - e1) end));
      -- anti-farming: after 3 ranked games today against the same opponent(s), no more rating changes
      select count(*) into repeats from battles ob join battle_players me on me.battle_id = ob.id and me.user_id = pl.user_id
      where ob.style = 'ranked' and ob.status = 'finished' and ob.id <> b.id
        and (ob.created_at at time zone 'Indian/Mauritius')::date = today_local()
        and exists (select 1 from battle_players o join battle_players cur on cur.user_id = o.user_id and cur.battle_id = b.id and cur.team <> pl.team
                    where o.battle_id = ob.id and o.team <> me.team);
      if repeats >= 3 then d := 0; end if;
      update profiles set rating = greatest(0, rating + d), ranked_played = ranked_played + 1,
        ranked_wins = ranked_wins + case when w = pl.team then 1 else 0 end where id = pl.user_id;
      update battle_players set rating_delta = d where battle_id = b.id and user_id = pl.user_id;
    end loop;
  end if;
end $$;
revoke execute on function battle_finish(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------- cards + leaderboard carry rating
drop function if exists profile_cards(uuid[]);
create function profile_cards(p_ids uuid[]) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, tier tier, name_style text, frame text, rating int, ranked_played int)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp), p.tier, p.name_style, p.frame, p.rating, p.ranked_played
  from profiles p where p.id = any(p_ids) and is_approved();
$$;
grant execute on function profile_cards(uuid[]) to authenticated;

create or replace function get_leaderboard(p_kind text, p_limit int default 50) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, value bigint, name_style text, frame text)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp),
         case p_kind
           when 'xp' then p.xp::bigint
           when 'ranked' then p.rating::bigint
           when 'monthly' then (select coalesce(sum(amount), 0) from xp_events e where e.user_id = p.id
                                  and e.created_at >= date_trunc('month', now()))
           when 'attendance' then (select count(*) from attendance a where a.user_id = p.id and a.status in ('present','late'))
           when 'speedrun' then (select coalesce(max(q.points), 0) from quiz_attempts q join quizzes z on z.id = q.quiz_id
                                  where q.user_id = p.id and z.kind = 'speedrun' and not q.flagged)
           when 'battles' then (select count(*) from battles b join battle_players bp on bp.battle_id = b.id
                                  where bp.user_id = p.id and b.status = 'finished' and b.winner_team = bp.team)
           else 0 end as value,
         p.name_style, p.frame
  from profiles p
  where p.status = 'approved' and p.role = 'student' and is_approved() and (p_kind <> 'ranked' or p.ranked_played > 0)
  order by value desc, p.xp desc
  limit p_limit;
$$;


-- ===== 0015_seasons.sql =====
-- Seasons: a leaderboard that resets each month and rewards the top players.
-- Season 1 = 1–30 December 2026 (Mauritius time). November is a warm-up and doesn't count.
-- When a season starts, ranked ratings reset to 1000. When it ends, the top 10 on Season XP and on Ranked
-- get exclusive titles, the Season frame/name style and coins, and the next season is created automatically.

-- ---------------------------------------------------------------- reward-only cosmetics (never sold, shown once owned)
alter table shop_items add column if not exists reward_only boolean not null default false;
drop policy if exists shop_select on shop_items;
create policy shop_select on shop_items for select using (
  is_approved() and (
    (active and not tutor_only and not reward_only) or is_tutor()
    or exists (select 1 from user_items u where u.item_id = shop_items.id and u.user_id = auth.uid())));

create or replace function buy_item(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype; prof profiles%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into it from shop_items where id = p_item and active and not tutor_only and not reward_only;
  if not found then raise exception 'item not available'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if level_from_xp(prof.xp) < it.min_level then raise exception 'reach level % to unlock this', it.min_level; end if;
  if prof.coins < it.price then raise exception 'not enough coins'; end if;
  if it.kind = 'streak_freeze' then
    if prof.streak_freezes >= 2 then raise exception 'you can only hold 2 streak freezes'; end if;
    update profiles set coins = coins - it.price, streak_freezes = streak_freezes + 1 where id = prof.id;
  else
    if exists (select 1 from user_items where user_id = prof.id and item_id = it.id) then raise exception 'you already own this'; end if;
    insert into user_items(user_id, item_id) values (prof.id, it.id);
    update profiles set coins = coins - it.price where id = prof.id;
  end if;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, 0, -it.price, 'shop', it.code);
  return jsonb_build_object('coins', prof.coins - it.price, 'kind', it.kind, 'code', it.code);
end $$;

-- the shared season cosmetics (titles are made per season when it ends)
insert into shop_items(code, kind, name, description, price, rarity, min_level, data, sort, active, reward_only)
values ('season', 'frame', 'Season Frame', 'Top 3 of a season only.', 0, 'legendary', 1, '{}'::jsonb, 900, false, true),
       ('season', 'name_style', 'Season Champion Name', 'Season #1 only.', 0, 'legendary', 1, '{}'::jsonb, 901, false, true)
on conflict (kind, code) do update set reward_only = true, active = false;

-- ---------------------------------------------------------------- seasons
create table if not exists seasons (
  id serial primary key,
  number int unique not null,
  name text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  status text not null default 'upcoming' check (status in ('upcoming', 'active', 'ended'))
);
create table if not exists season_results (
  season_id int not null references seasons(id) on delete cascade,
  board text not null check (board in ('xp', 'ranked')),
  place int not null,
  user_id uuid not null references profiles(id) on delete cascade,
  value int not null,
  primary key (season_id, board, place)
);
alter table seasons enable row level security;
alter table season_results enable row level security;
drop policy if exists seasons_select on seasons;
create policy seasons_select on seasons for select using (is_approved());
drop policy if exists season_results_select on season_results;
create policy season_results_select on season_results for select using (is_approved());
grant select on seasons, season_results to authenticated;
grant all on seasons, season_results to service_role;

insert into seasons(number, name, starts_at, ends_at)
values (1, 'Season 1', '2026-12-01 00:00:00+04', '2026-12-30 23:59:59+04')
on conflict (number) do nothing;

-- give one reward item (creating per-season titles on the fly)
create or replace function season_give(p_user uuid, p_kind text, p_code text, p_name text, p_text text) returns void
language plpgsql security definer set search_path = public as $$
declare it uuid;
begin
  insert into shop_items(code, kind, name, description, price, rarity, min_level, data, sort, active, reward_only)
  values (p_code, p_kind, p_name, 'Season reward.', 0, 'legendary', 1,
          case when p_text is null then '{}'::jsonb else jsonb_build_object('text', p_text) end, 950, false, true)
  on conflict (kind, code) do nothing;
  select id into it from shop_items where kind = p_kind and code = p_code;
  insert into user_items(user_id, item_id) values (p_user, it) on conflict do nothing;
end $$;

-- end a season: record top 10 on both boards and hand out rewards
create or replace function season_award(p_season int) returns void
language plpgsql security definer set search_path = public as $$
declare s seasons%rowtype; r record; brd text; coins int; tag text;
begin
  select * into s from seasons where id = p_season;
  if exists (select 1 from season_results where season_id = s.id) then return; end if;
  tag := 'S' || s.number;
  foreach brd in array array['xp', 'ranked'] loop
    for r in
      select x.id, x.value, row_number() over (order by x.value desc, x.xp desc) as place from (
        select p.id, p.xp,
               case brd when 'xp' then (select coalesce(sum(e.amount), 0) from xp_events e
                                        where e.user_id = p.id and e.created_at >= s.starts_at and e.created_at < s.ends_at)
                        else p.rating end::int as value
        from profiles p
        where p.role = 'student' and p.status = 'approved' and (brd <> 'ranked' or p.ranked_played > 0)) x
      where x.value > 0
      order by x.value desc, x.xp desc limit 10
    loop
      insert into season_results(season_id, board, place, user_id, value) values (s.id, brd, r.place, r.id, r.value);
      coins := case r.place when 1 then 1000 when 2 then 600 when 3 then 400 else 150 end;
      perform award_xp(r.id, 0, 'season', s.name || ' ' || brd || ' #' || r.place, null, coins, false);
      if r.place = 1 then
        perform season_give(r.id, 'title', lower(tag) || '-' || brd || '-champ', s.name || (case brd when 'xp' then ' XP Champion' else ' Ranked Champion' end),
                            case brd when 'xp' then '👑 ' || tag || ' XP Champion' else '🏆 ' || tag || ' Ranked Champion' end);
        perform season_give(r.id, 'name_style', 'season', 'Season Champion Name', null);
      end if;
      if r.place <= 3 then
        perform season_give(r.id, 'title', lower(tag) || '-top3', s.name || ' Top 3', '🥈 ' || tag || ' Top 3');
        perform season_give(r.id, 'frame', 'season', 'Season Frame', null);
      end if;
      perform season_give(r.id, 'title', lower(tag) || '-top10', s.name || ' Top 10', '⭐ ' || tag || ' Top 10');
      perform notify(r.id, '🏆 ' || s.name || ' rewards!',
        'You finished #' || r.place || ' on the ' || case brd when 'xp' then 'Season XP' else 'Ranked' end
        || ' leaderboard: +' || coins || ' coins and new cosmetics. Equip them in the Shop!', '/shop');
    end loop;
  end loop;
end $$;

-- moves seasons along; safe to call any time (the leaderboard, battles page and daily cron call it)
create or replace function season_tick() returns void
language plpgsql security definer set search_path = public as $$
declare s seasons%rowtype; nxt_start timestamptz; nxt_end timestamptz; guard int := 0;
begin
  loop
    guard := guard + 1; exit when guard > 6;
    select * into s from seasons where status = 'active' and ends_at <= now() order by number limit 1 for update skip locked;
    if found then
      perform season_award(s.id);
      update seasons set status = 'ended' where id = s.id;
      if not exists (select 1 from seasons where number = s.number + 1) then
        -- next season: from the end of this one to the end of the following month (Mauritius time)
        nxt_start := s.ends_at + interval '1 second';
        nxt_end := ((date_trunc('month', (nxt_start at time zone 'Indian/Mauritius') + interval '1 day') + interval '1 month' - interval '1 second')
                    at time zone 'Indian/Mauritius');
        if nxt_end - nxt_start < interval '20 days' then   -- too short: run to the end of the month after
          nxt_end := ((date_trunc('month', (nxt_start at time zone 'Indian/Mauritius') + interval '1 day') + interval '2 months' - interval '1 second')
                      at time zone 'Indian/Mauritius');
        end if;
        insert into seasons(number, name, starts_at, ends_at) values (s.number + 1, 'Season ' || (s.number + 1), nxt_start, nxt_end);
      end if;
      continue;
    end if;
    select * into s from seasons where status = 'upcoming' and starts_at <= now() order by number limit 1 for update skip locked;
    if found then
      update seasons set status = 'active' where id = s.id;
      update profiles set rating = 1000, ranked_played = 0, ranked_wins = 0;   -- fresh ranked ladder each season
      continue;
    end if;
    exit;
  end loop;
end $$;

-- tutor controls
create or replace function tutor_set_season(p_id int, p_starts timestamptz, p_ends timestamptz) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  if p_ends <= p_starts then raise exception 'the end must be after the start'; end if;
  update seasons set starts_at = case when status = 'upcoming' then p_starts else starts_at end, ends_at = p_ends
  where id = p_id and status <> 'ended';
end $$;
create or replace function tutor_end_season(p_id int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  update seasons set ends_at = now() where id = p_id and status = 'active';
  perform season_tick();
end $$;

revoke all on function season_give(uuid, text, text, text, text) from public, anon, authenticated;
revoke all on function season_award(int) from public, anon, authenticated;
revoke all on function season_tick() from public, anon;
grant execute on function season_tick() to authenticated, service_role;
revoke all on function tutor_set_season(int, timestamptz, timestamptz) from public, anon;
revoke all on function tutor_end_season(int) from public, anon;
grant execute on function tutor_set_season(int, timestamptz, timestamptz) to authenticated;
grant execute on function tutor_end_season(int) to authenticated;

-- ---------------------------------------------------------------- leaderboard: Season XP
create or replace function get_leaderboard(p_kind text, p_limit int default 50) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, value bigint, name_style text, frame text)
language sql stable security definer set search_path = public as $$
  with cur as (select starts_at, ends_at from seasons where status = 'active' order by number desc limit 1)
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp),
         case p_kind
           when 'xp' then p.xp::bigint
           when 'season' then (select coalesce(sum(e.amount), 0) from xp_events e, cur
                                 where e.user_id = p.id and e.created_at >= cur.starts_at and e.created_at < cur.ends_at)
           when 'ranked' then p.rating::bigint
           when 'monthly' then (select coalesce(sum(amount), 0) from xp_events e where e.user_id = p.id
                                  and e.created_at >= date_trunc('month', now()))
           when 'attendance' then (select count(*) from attendance a where a.user_id = p.id and a.status in ('present','late'))
           when 'speedrun' then (select coalesce(max(q.points), 0) from quiz_attempts q join quizzes z on z.id = q.quiz_id
                                  where q.user_id = p.id and z.kind = 'speedrun' and not q.flagged)
           when 'battles' then (select count(*) from battles b join battle_players bp on bp.battle_id = b.id
                                  where bp.user_id = p.id and b.status = 'finished' and b.winner_team = bp.team)
           else 0 end as value,
         p.name_style, p.frame
  from profiles p
  where p.status = 'approved' and p.role = 'student' and is_approved()
    and (p_kind <> 'ranked' or p.ranked_played > 0)
    and (p_kind <> 'season' or exists (select 1 from cur))
  order by value desc, p.xp desc
  limit p_limit;
$$;


-- ===== 0016_prestige.sql =====
-- Prestige (like CoD): at Level 20 a student can reset their level to 1 for a Prestige emblem and rewards.
-- Each prestige also gives +0.15x XP on everything (P1 = 1.15x … P10 = 2.5x). Students who don't prestige keep levelling.
-- Their XP moves into lifetime_xp, so the All-time XP leaderboard still counts it. Nothing they own is lost,
-- and level unlocks stay unlocked after their first prestige.
alter table profiles add column if not exists prestige int not null default 0;
alter table profiles add column if not exists lifetime_xp bigint not null default 0;

-- unlock level for shop items/hats: once you've prestiged you keep everything up to Level 20 unlocked
create or replace function unlock_level(p_xp int, p_prestige int) returns int language sql immutable as $$
  select case when p_prestige > 0 then greatest(level_from_xp(p_xp), 20) else level_from_xp(p_xp) end;
$$;

insert into shop_items(code, kind, name, description, price, rarity, min_level, data, sort, active, reward_only)
values ('prestige', 'frame', 'Prestige Frame', 'Prestige 1 reward.', 0, 'legendary', 1, '{}'::jsonb, 910, false, true),
       ('prestige', 'name_style', 'Prestige Name', 'Prestige 5 reward.', 0, 'legendary', 1, '{}'::jsonb, 911, false, true),
       ('master', 'frame', 'Master Prestige Frame', 'Prestige 10 reward.', 0, 'legendary', 1, '{}'::jsonb, 912, false, true)
on conflict (kind, code) do update set reward_only = true, active = false;

create or replace function do_prestige() returns jsonb
language plpgsql security definer set search_path = public as $$
declare prof profiles%rowtype; n int; v_coins int;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if prof.role <> 'student' then raise exception 'only students can prestige'; end if;
  if prof.prestige >= 10 then raise exception 'you are already Master Prestige'; end if;
  if level_from_xp(prof.xp) < 20 then raise exception 'reach Level 20 to prestige'; end if;
  n := prof.prestige + 1;
  v_coins := 500 * n;
  update profiles set lifetime_xp = lifetime_xp + xp, xp = 0, prestige = n, coins = profiles.coins + v_coins, announced_level = 1
  where id = prof.id;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, 0, v_coins, 'prestige', 'P' || n);
  perform season_give(prof.id, 'title', 'prestige-' || n, case when n = 10 then 'Master Prestige' else 'Prestige ' || n end,
                      case when n = 10 then '💠 Master Prestige' else '⭐ Prestige ' || n end);
  if n = 1 then perform season_give(prof.id, 'frame', 'prestige', 'Prestige Frame', null); end if;
  if n = 5 then perform season_give(prof.id, 'name_style', 'prestige', 'Prestige Name', null); end if;
  if n = 10 then perform season_give(prof.id, 'frame', 'master', 'Master Prestige Frame', null); end if;
  perform notify(prof.id, case when n = 10 then '💠 MASTER PRESTIGE!' else '⭐ Prestige ' || n || '!' end,
    '+' || v_coins || ' coins and new cosmetics. Equip them in the Shop!', '/shop');
  return jsonb_build_object('prestige', n, 'coins', v_coins);
end $$;
revoke all on function do_prestige() from public, anon;
grant execute on function do_prestige() to authenticated;

-- shop: level unlocks use unlock_level
create or replace function buy_item(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype; prof profiles%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into it from shop_items where id = p_item and active and not tutor_only and not reward_only;
  if not found then raise exception 'item not available'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if unlock_level(prof.xp, prof.prestige) < it.min_level then raise exception 'reach level % to unlock this', it.min_level; end if;
  if prof.coins < it.price then raise exception 'not enough coins'; end if;
  if it.kind = 'streak_freeze' then
    if prof.streak_freezes >= 2 then raise exception 'you can only hold 2 streak freezes'; end if;
    update profiles set coins = coins - it.price, streak_freezes = streak_freezes + 1 where id = prof.id;
  else
    if exists (select 1 from user_items where user_id = prof.id and item_id = it.id) then raise exception 'you already own this'; end if;
    insert into user_items(user_id, item_id) values (prof.id, it.id);
    update profiles set coins = coins - it.price where id = prof.id;
  end if;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, 0, -it.price, 'shop', it.code);
  return jsonb_build_object('coins', prof.coins - it.price, 'kind', it.kind, 'code', it.code);
end $$;

-- cards and leaderboard carry the prestige emblem; All-time XP = lifetime + current
drop function if exists profile_cards(uuid[]);
create function profile_cards(p_ids uuid[]) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, tier tier, name_style text, frame text, rating int, ranked_played int, prestige int)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp), p.tier, p.name_style, p.frame, p.rating, p.ranked_played, p.prestige
  from profiles p where p.id = any(p_ids) and is_approved();
$$;
grant execute on function profile_cards(uuid[]) to authenticated;

drop function if exists get_leaderboard(text, int);
create function get_leaderboard(p_kind text, p_limit int default 50) returns table(
  id uuid, display_name text, avatar_mode text, discord_avatar_url text, roblox_headshot_url text,
  blocky jsonb, title text, level int, value bigint, name_style text, frame text, prestige int)
language sql stable security definer set search_path = public as $$
  with cur as (select starts_at, ends_at from seasons where status = 'active' order by number desc limit 1)
  select p.id, p.display_name, p.avatar_mode, p.discord_avatar_url, p.roblox_headshot_url, p.blocky, p.title,
         level_from_xp(p.xp),
         case p_kind
           when 'xp' then p.lifetime_xp + p.xp
           when 'season' then (select coalesce(sum(e.amount), 0) from xp_events e, cur
                                 where e.user_id = p.id and e.created_at >= cur.starts_at and e.created_at < cur.ends_at)
           when 'ranked' then p.rating::bigint
           when 'monthly' then (select coalesce(sum(amount), 0) from xp_events e where e.user_id = p.id
                                  and e.created_at >= date_trunc('month', now()))
           when 'attendance' then (select count(*) from attendance a where a.user_id = p.id and a.status in ('present','late'))
           when 'speedrun' then (select coalesce(max(q.points), 0) from quiz_attempts q join quizzes z on z.id = q.quiz_id
                                  where q.user_id = p.id and z.kind = 'speedrun' and not q.flagged)
           when 'battles' then (select count(*) from battles b join battle_players bp on bp.battle_id = b.id
                                  where bp.user_id = p.id and b.status = 'finished' and b.winner_team = bp.team)
           else 0 end as value,
         p.name_style, p.frame, p.prestige
  from profiles p
  where p.status = 'approved' and p.role = 'student' and is_approved()
    and (p_kind <> 'ranked' or p.ranked_played > 0)
    and (p_kind <> 'season' or exists (select 1 from cur))
  order by value desc, p.xp desc
  limit p_limit;
$$;
grant execute on function get_leaderboard(text, int) to authenticated;


-- ---------------------------------------------------------------- balance: gentler level curve
-- Total XP for level L is now 40·L·(L-1) (was 50): Level 10 = 3 600, Level 20 = 15 200.
-- About 8 weeks of regular study (5 days a week, classes, quests) to reach Level 20 and prestige.
-- Everyone's level is worked out from their XP, so current students move up a little; nobody drops.
create or replace function level_from_xp(x int) returns int language sql immutable as $$
  select greatest(1, floor((1 + sqrt(1 + 4 * x / 40.0)) / 2)::int);
$$;

-- ---------------------------------------------------------------- prestige XP boost
create or replace function award_xp(
  p_user uuid, p_base int, p_reason text, p_ref text default null,
  p_content_tier tier default null, p_coins int default 0, p_counts_study boolean default true
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  prof profiles%rowtype;
  mult numeric := 1;
  gained int;
  lvl_before int;
  lvl_after int;
  today date := today_local();
  new_day boolean := false;
  missed int;
  keeps boolean;
begin
  select * into prof from profiles where id = p_user for update;
  if not found or (p_base <= 0 and p_coins <= 0 and not p_counts_study) then
    return jsonb_build_object('xp', 0, 'leveled_up', false);
  end if;
  if p_content_tier is not null then
    mult := 1 + 0.25 * greatest(0, tier_rank(p_content_tier) - tier_rank(prof.tier));
  end if;
  mult := mult * (1 + 0.15 * coalesce(prof.prestige, 0));   -- prestige boost: +0.15x per prestige
  gained := round(greatest(p_base, 0) * mult);
  lvl_before := level_from_xp(prof.xp);

  if gained > 0 or p_coins > 0 then
    insert into xp_events(user_id, amount, coins, multiplier, reason, ref)
    values (p_user, gained, p_coins, mult, p_reason, p_ref);
    update profiles set xp = xp + gained, coins = coins + p_coins where id = p_user;
  end if;

  if p_counts_study and (prof.last_study_date is null or prof.last_study_date < today) then
    new_day := true;
    missed := case when prof.last_study_date is null then 999 else today - prof.last_study_date - 1 end;
    -- streak continues if no day was missed, or if streak freezes cover every missed day
    keeps := missed = 0 or (missed between 1 and prof.streak_freezes and prof.streak > 0);
    update profiles set
      streak = case when keeps then prof.streak + 1 else 1 end,
      best_streak = greatest(prof.best_streak, case when keeps then prof.streak + 1 else 1 end),
      streak_freezes = case when keeps and missed > 0 then prof.streak_freezes - missed else prof.streak_freezes end,
      last_study_date = today
    where id = p_user;
    if keeps and missed > 0 then
      perform notify(p_user, '🧊 Streak freeze used', 'You missed ' || missed || ' day' || case when missed > 1 then 's' else '' end
        || ', but your ' || (prof.streak + 1) || '-day streak survived.', '/shop');
    end if;
  end if;

  lvl_after := level_from_xp(prof.xp + gained);
  if lvl_after > lvl_before then
    perform notify(p_user, 'Level up! You reached Lv ' || lvl_after, null, '/dashboard');
  end if;

  if p_reason <> 'challenge' and gained > 0 then
    perform bump_challenge(p_user, 'xp_earned', gained, null);
  end if;
  if new_day then
    perform bump_challenge(p_user, 'study_days', 1, null);
  end if;

  return jsonb_build_object('xp', gained, 'multiplier', mult, 'level_before', lvl_before,
                            'level_after', lvl_after, 'leveled_up', lvl_after > lvl_before);
end $$;
revoke execute on function award_xp(uuid,int,text,text,tier,int,boolean) from public, anon, authenticated;


-- ===== 0017_powerups_black_market.sql =====
-- Power-ups (Homework Extension) and the secret Black Market (Bunk Card, Skip Homework Pass).

-- ---------------------------------------------------------------- "online" ping (lets the black market know if the owner is around)
create or replace function touch_seen() returns void
language sql security definer set search_path = public as $$
  update profiles set last_seen_at = now()
  where id = auth.uid() and (last_seen_at is null or last_seen_at < now() - interval '45 seconds');
$$;
revoke all on function touch_seen() from public, anon;
grant execute on function touch_seen() to authenticated;

-- ---------------------------------------------------------------- per-student homework changes (extensions, skips)
create table if not exists assignment_overrides (
  assignment_id uuid not null references assignments(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  extra_hours int not null default 0,
  exempt boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (assignment_id, user_id)
);
alter table assignment_overrides enable row level security;
drop policy if exists overrides_select on assignment_overrides;
create policy overrides_select on assignment_overrides for select using (user_id = auth.uid() or is_tutor());
grant select on assignment_overrides to authenticated;
grant all on assignment_overrides to service_role;

-- consumable power-ups you hold
create table if not exists user_powerups (
  user_id uuid not null references profiles(id) on delete cascade,
  code text not null,
  qty int not null default 0 check (qty >= 0),
  primary key (user_id, code)
);
alter table user_powerups enable row level security;
drop policy if exists powerups_select on user_powerups;
create policy powerups_select on user_powerups for select using (user_id = auth.uid() or is_tutor());
grant select on user_powerups to authenticated;
grant all on user_powerups to service_role;

alter table shop_items drop constraint if exists shop_items_kind_check;
alter table shop_items add constraint shop_items_kind_check
  check (kind in ('title', 'name_style', 'frame', 'hat', 'pattern', 'streak_freeze', 'face_acc', 'back', 'powerup'));
insert into shop_items(code, kind, name, description, price, rarity, min_level, data, sort, active)
values ('extension', 'powerup', 'Homework Extension', '+48 hours on one homework deadline. Hold up to 2.', 120, 'rare', 3, '{}'::jsonb, 200, true)
on conflict (kind, code) do nothing;

create or replace function buy_item(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare it shop_items%rowtype; prof profiles%rowtype; held int;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into it from shop_items where id = p_item and active and not tutor_only and not reward_only;
  if not found then raise exception 'item not available'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if unlock_level(prof.xp, prof.prestige) < it.min_level then raise exception 'reach level % to unlock this', it.min_level; end if;
  if prof.coins < it.price then raise exception 'not enough coins'; end if;
  if it.kind = 'streak_freeze' then
    if prof.streak_freezes >= 2 then raise exception 'you can only hold 2 streak freezes'; end if;
    update profiles set coins = coins - it.price, streak_freezes = streak_freezes + 1 where id = prof.id;
  elsif it.kind = 'powerup' then
    select coalesce(qty, 0) into held from user_powerups where user_id = prof.id and code = it.code;
    if coalesce(held, 0) >= 2 then raise exception 'you can only hold 2 of these'; end if;
    insert into user_powerups(user_id, code, qty) values (prof.id, it.code, 1)
    on conflict (user_id, code) do update set qty = user_powerups.qty + 1;
    update profiles set coins = coins - it.price where id = prof.id;
  else
    if exists (select 1 from user_items where user_id = prof.id and item_id = it.id) then raise exception 'you already own this'; end if;
    insert into user_items(user_id, item_id) values (prof.id, it.id);
    update profiles set coins = coins - it.price where id = prof.id;
  end if;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, 0, -it.price, 'shop', it.code);
  return jsonb_build_object('coins', prof.coins - it.price, 'kind', it.kind, 'code', it.code);
end $$;

-- use a Homework Extension: +48h on one assignment you haven't handed in (once per assignment, up to 24h after it was due)
create or replace function use_extension(p_assignment uuid) returns timestamptz
language plpgsql security definer set search_path = public as $$
declare a assignments%rowtype; ov assignment_overrides%rowtype;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into a from assignments where id = p_assignment;
  if not found or a.due_at is null then raise exception 'this homework has no deadline'; end if;
  if exists (select 1 from submissions where assignment_id = a.id and user_id = auth.uid()) then raise exception 'already handed in'; end if;
  select * into ov from assignment_overrides where assignment_id = a.id and user_id = auth.uid();
  if found and ov.extra_hours > 0 then raise exception 'you already extended this one'; end if;
  if now() > a.due_at + interval '24 hours' then raise exception 'too late to extend this one'; end if;
  update user_powerups set qty = qty - 1 where user_id = auth.uid() and code = 'extension' and qty > 0;
  if not found then raise exception 'you have no extensions: buy one in the shop'; end if;
  insert into assignment_overrides(assignment_id, user_id, extra_hours) values (a.id, auth.uid(), 48)
  on conflict (assignment_id, user_id) do update set extra_hours = 48;
  return a.due_at + interval '48 hours';
end $$;
revoke all on function use_extension(uuid) from public, anon;
grant execute on function use_extension(uuid) to authenticated;

-- marking counts an extended deadline as on time
create or replace function grade_submission(p_submission uuid, p_score int, p_feedback text)
returns void language plpgsql security definer set search_path = public as $$
declare s submissions%rowtype; a assignments%rowtype; c courses%rowtype; first_grade boolean; extra int;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  select * into s from submissions where id = p_submission for update;
  select * into a from assignments where id = s.assignment_id;
  select * into c from courses where id = a.course_id;
  select coalesce(extra_hours, 0) into extra from assignment_overrides where assignment_id = a.id and user_id = s.user_id;
  first_grade := s.graded_at is null;
  update submissions set score = p_score, feedback = p_feedback, graded_at = now() where id = s.id;
  if first_grade then
    perform award_xp(s.user_id, round(a.xp_reward * least(1, greatest(0, p_score::numeric / a.max_score)))::int
                     + 20, 'homework', a.id::text, c.tier, 10, true);
    if a.due_at is null or s.submitted_at <= a.due_at + make_interval(hours => coalesce(extra, 0)) then
      perform bump_challenge(s.user_id, 'homework_on_time', 1, null);
    end if;
    perform check_achievements(s.user_id);
  end if;
  perform notify(s.user_id, 'Marked: ' || a.title, p_score || ' / ' || a.max_score, '/homework');
end $$;

-- ---------------------------------------------------------------- 🕶️ the black market
-- Every deal is logged here. Only the tutor can read it (but the shop UI never shows it: you'd have to look).
create table if not exists black_market_log (
  id bigserial primary key,
  user_id uuid not null references profiles(id) on delete cascade,
  item text not null,
  target uuid,
  coins int not null,
  xp int not null,
  owner_alerted boolean not null default false,
  created_at timestamptz not null default now()
);
alter table black_market_log enable row level security;
drop policy if exists bm_select on black_market_log;
create policy bm_select on black_market_log for select using (user_id = auth.uid() or is_tutor());
grant select on black_market_log to authenticated;
grant all on black_market_log to service_role;

-- what the seller has, and whether the owner is around
create or replace function black_market_status() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'owner_online', exists (select 1 from profiles where role = 'tutor' and last_seen_at > now() - interval '3 minutes'),
    'uses', jsonb_build_object(
      'bunk', (select count(*) from black_market_log where user_id = auth.uid() and item = 'bunk'),
      'skip', (select count(*) from black_market_log where user_id = auth.uid() and item = 'skip')),
    'max_uses', 3,
    'prices', jsonb_build_object(
      'bunk', jsonb_build_object('coins', 2500, 'xp', 1500),
      'skip', jsonb_build_object('coins', 3500, 'xp', 2500)))
  where is_approved();
$$;
revoke all on function black_market_status() from public, anon;
grant execute on function black_market_status() to authenticated;

create or replace function black_market_buy(p_item text, p_target uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare prof profiles%rowtype; price_c int; price_x int; used int; tgt_title text; alerted boolean := false; t record;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into prof from profiles where id = auth.uid() for update;
  if prof.role <> 'student' then raise exception 'the seller doesn''t deal with the owner. Nice try.'; end if;
  if p_item not in ('bunk', 'skip') then raise exception 'never heard of it'; end if;
  price_c := case p_item when 'bunk' then 2500 else 3500 end;
  price_x := case p_item when 'bunk' then 1500 else 2500 end;
  select count(*) into used from black_market_log where user_id = prof.id and item = p_item;
  if used >= 3 then raise exception 'it''s broken. The seller won''t sell you another.'; end if;
  if prof.coins < price_c then raise exception 'not enough coins, kid'; end if;
  if prof.xp < price_x then raise exception 'not enough XP, kid'; end if;

  if p_item = 'skip' then
    select a.title into tgt_title from assignments a where a.id = p_target;
    if tgt_title is null then raise exception 'no such homework'; end if;
    if exists (select 1 from submissions where assignment_id = p_target and user_id = prof.id) then raise exception 'you already handed that in'; end if;
    if exists (select 1 from assignment_overrides where assignment_id = p_target and user_id = prof.id and exempt) then raise exception 'already skipped'; end if;
    insert into assignment_overrides(assignment_id, user_id, exempt) values (p_target, prof.id, true)
    on conflict (assignment_id, user_id) do update set exempt = true;
  else
    select s.title, s.held_on into t from attendance a join class_sessions s on s.id = a.session_id
    where a.session_id = p_target and a.user_id = prof.id and a.status = 'absent' and s.held_on >= current_date - 30;
    if not found then raise exception 'no absence like that in the last 30 days'; end if;
    tgt_title := t.title || ' (' || to_char(t.held_on, 'DD Mon') || ')';
    update attendance set status = 'excused' where session_id = p_target and user_id = prof.id;
  end if;

  -- pay: coins and XP (a negative XP event, so the season leaderboard drops too)
  update profiles set coins = coins - price_c, xp = xp - price_x where id = prof.id;
  insert into xp_events(user_id, amount, coins, reason, ref) values (prof.id, -price_x, -price_c, 'black_market', p_item);

  -- 50% chance the owner sees it, but only if they're online right now
  if exists (select 1 from profiles where role = 'tutor' and last_seen_at > now() - interval '3 minutes') and random() < 0.5 then
    alerted := true;
    perform notify(p.id, '🕵️ Black market deal spotted!',
      prof.display_name || ' just bought a ' || case p_item when 'bunk' then 'Bunk Card' else 'Skip Homework Pass' end || ' for "' || tgt_title || '"', '/tutor/students/' || prof.id)
    from profiles p where p.role = 'tutor';
  end if;
  insert into black_market_log(user_id, item, target, coins, xp, owner_alerted) values (prof.id, p_item, p_target, price_c, price_x, alerted);
  return jsonb_build_object('uses_left', 3 - used - 1, 'caught', alerted);
end $$;
revoke all on function black_market_buy(text, uuid) from public, anon;
grant execute on function black_market_buy(text, uuid) to authenticated;


-- ===== 0018_arcade.sql =====
-- 🕹️ Arcade: learning mini-games. A win pays XP + coins once per game per day; losing costs nothing.
-- Every play is logged (score, win/lose) so the tutor can see who's practising what.
create table if not exists arcade_plays (
  id bigserial primary key,
  user_id uuid not null references profiles(id) on delete cascade,
  game text not null,
  score int not null default 0,
  success boolean not null default false,
  xp int not null default 0,
  coins int not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists arcade_user_game on arcade_plays(user_id, game, created_at desc);
alter table arcade_plays enable row level security;
drop policy if exists arcade_select on arcade_plays;
create policy arcade_select on arcade_plays for select using (user_id = auth.uid() or is_tutor());
grant select on arcade_plays to authenticated;
grant all on arcade_plays to service_role;
grant usage, select on sequence arcade_plays_id_seq to service_role;

create or replace function arcade_finish(p_game text, p_score int, p_success boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare paid_today boolean; xp_gain int := 0; coin_gain int := 0; res jsonb;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_game not in ('ip-blaster-v4', 'ip-blaster-v6', 'cpu-commander', 'embedded-sorter') then raise exception 'unknown game'; end if;
  -- one rewarded win per game per day (Mauritius time), so it can't be farmed
  select exists (select 1 from arcade_plays where user_id = auth.uid() and game = p_game and xp > 0
                 and (created_at at time zone 'Indian/Mauritius')::date = today_local()) into paid_today;
  if coalesce(p_success, false) and not paid_today then
    res := award_xp(auth.uid(), 40, 'arcade', p_game, null, 10, true);
    xp_gain := coalesce((res->>'xp')::int, 0);
    coin_gain := 10;
  end if;
  insert into arcade_plays(user_id, game, score, success, xp, coins)
  values (auth.uid(), p_game, greatest(0, least(coalesce(p_score, 0), 100000)), coalesce(p_success, false), xp_gain, coin_gain);
  return jsonb_build_object('xp', xp_gain, 'coins', coin_gain, 'already_paid_today', paid_today and coalesce(p_success, false));
end $$;
revoke all on function arcade_finish(text, int, boolean) from public, anon;
grant execute on function arcade_finish(text, int, boolean) to authenticated;


-- ===== 0019_special_training.sql =====
-- 🌟 Special Training + 🧮 Trace Master.
-- profiles.special: set by the tutor only (students have no UPDATE grant on it, and other
-- students can't read it because profiles RLS only shows your own row).
alter table profiles add column if not exists special boolean not null default false;

-- Arcade gains the four Trace Master modes. Pro mode only pays special students (and the tutor).
create or replace function arcade_finish(p_game text, p_score int, p_success boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare paid_today boolean; xp_gain int := 0; coin_gain int := 0; res jsonb;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  if p_game not in ('ip-blaster-v4', 'ip-blaster-v6', 'cpu-commander', 'embedded-sorter',
                    'trace-o', 'trace-as', 'trace-a', 'trace-pro') then raise exception 'unknown game'; end if;
  if p_game = 'trace-pro' and not is_tutor()
     and not coalesce((select special from profiles where id = auth.uid()), false) then
    raise exception 'special training only';
  end if;
  -- one rewarded win per game per day (Mauritius time), so it can't be farmed
  select exists (select 1 from arcade_plays where user_id = auth.uid() and game = p_game and xp > 0
                 and (created_at at time zone 'Indian/Mauritius')::date = today_local()) into paid_today;
  if coalesce(p_success, false) and not paid_today then
    res := award_xp(auth.uid(), 40, 'arcade', p_game, null, 10, true);
    xp_gain := coalesce((res->>'xp')::int, 0);
    coin_gain := 10;
  end if;
  insert into arcade_plays(user_id, game, score, success, xp, coins)
  values (auth.uid(), p_game, greatest(0, least(coalesce(p_score, 0), 100000)), coalesce(p_success, false), xp_gain, coin_gain);
  return jsonb_build_object('xp', xp_gain, 'coins', coin_gain, 'already_paid_today', paid_today and coalesce(p_success, false));
end $$;
revoke all on function arcade_finish(text, int, boolean) from public, anon;
grant execute on function arcade_finish(text, int, boolean) to authenticated;


-- ===== 0020_live_lessons.sql =====
-- 🎬 Live lessons: the tutor drives an interactive visualization on everyone's screen.
-- Only the tutor can move between steps or change the shared state (sliders etc.).
-- At checkpoints students answer a task; answers are checked HERE against live_keys
-- (students can't read the keys), one try per checkpoint, small capped rewards.

-- menu style switch (new hub menu vs the classic long menu), set by the tutor
alter table site_settings add column if not exists nav_style text not null default 'new';
do $$ begin
  alter table site_settings add constraint nav_style_ok check (nav_style in ('new', 'classic'));
exception when duplicate_object then null; end $$;

create or replace function tutor_set_nav_style(p_style text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  if p_style not in ('new', 'classic') then raise exception 'bad style'; end if;
  update site_settings set nav_style = p_style where id = 1;
end $$;
revoke all on function tutor_set_nav_style(text) from public, anon;
grant execute on function tutor_set_nav_style(text) to authenticated;

create table if not exists live_sessions (
  id uuid primary key default gen_random_uuid(),
  viz text not null check (char_length(viz) between 1 and 60),
  step int not null default 0 check (step between 0 and 200),
  state jsonb not null default '{}'::jsonb,        -- shared interactive state (e.g. a slider), tutor-controlled
  reveal boolean not null default false,          -- tutor has revealed the answer for the current checkpoint
  status text not null default 'live' check (status in ('live', 'ended')),
  started_by uuid references profiles(id) on delete set null,
  started_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  ended_at timestamptz
);
create index if not exists live_sessions_status on live_sessions(status, started_at desc);

create table if not exists live_answers (
  session_id uuid not null references live_sessions(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  step int not null,
  answer jsonb not null,
  correct boolean not null,
  xp int not null default 0,
  coins int not null default 0,
  created_at timestamptz not null default now(),
  primary key (session_id, user_id, step)
);

-- correct answers per visualization checkpoint (kept in sync with src/lib/viz by scripts/check-viz-keys)
create table if not exists live_keys (
  viz text not null,
  step int not null,
  answer jsonb not null,
  primary key (viz, step)
);

alter table live_sessions enable row level security;
alter table live_answers enable row level security;
alter table live_keys enable row level security;
drop policy if exists live_sessions_select on live_sessions;
create policy live_sessions_select on live_sessions for select using (is_approved());
drop policy if exists live_answers_select on live_answers;
create policy live_answers_select on live_answers for select using (user_id = auth.uid() or is_tutor());
drop policy if exists live_keys_select on live_keys;
create policy live_keys_select on live_keys for select using (is_tutor());   -- students never read keys
grant select on live_sessions, live_answers, live_keys to authenticated;
grant all on live_sessions, live_answers, live_keys to service_role;

create or replace function live_start(p_viz text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v uuid;
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  if p_viz !~ '^[a-z0-9-]{1,60}$' then raise exception 'unknown lesson'; end if;
  update live_sessions set status = 'ended', ended_at = now() where status = 'live';   -- one live lesson at a time
  insert into live_sessions(viz, started_by) values (p_viz, auth.uid()) returning id into v;
  return v;
end $$;

create or replace function live_goto(p_session uuid, p_step int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  update live_sessions set step = greatest(0, least(p_step, 200)), reveal = false, updated_at = now()
  where id = p_session and status = 'live';
end $$;

create or replace function live_set_state(p_session uuid, p_state jsonb) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  if pg_column_size(p_state) > 2000 then raise exception 'state too big'; end if;
  update live_sessions set state = coalesce(p_state, '{}'::jsonb), updated_at = now() where id = p_session and status = 'live';
end $$;

create or replace function live_reveal(p_session uuid, p_on boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  update live_sessions set reveal = coalesce(p_on, true), updated_at = now() where id = p_session and status = 'live';
end $$;

create or replace function live_end(p_session uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_tutor() then raise exception 'tutor only'; end if;
  update live_sessions set status = 'ended', ended_at = now(), updated_at = now() where id = p_session and status = 'live';
end $$;

-- A student answers the CURRENT checkpoint. One try only. Correct = +10 XP +2 coins,
-- capped at 100 XP of live-lesson rewards per day (Mauritius time).
create or replace function live_answer(p_session uuid, p_step int, p_answer jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare s live_sessions%rowtype; k jsonb; ok boolean; prev live_answers%rowtype;
        today_xp int; xp_gain int := 0; coin_gain int := 0; res jsonb;
begin
  if not is_approved() then raise exception 'not approved'; end if;
  select * into s from live_sessions where id = p_session;
  if not found or s.status <> 'live' then raise exception 'lesson ended'; end if;
  if s.step <> p_step then raise exception 'this checkpoint has moved on'; end if;
  if s.reveal then raise exception 'answers are closed for this checkpoint'; end if;
  select answer into k from live_keys where viz = s.viz and step = p_step;
  if k is null then raise exception 'no task here'; end if;
  select * into prev from live_answers where session_id = p_session and user_id = auth.uid() and step = p_step;
  if found then
    return jsonb_build_object('correct', prev.correct, 'xp', 0, 'coins', 0, 'already', true);
  end if;
  ok := (p_answer = k);
  if ok and not is_tutor() then
    select coalesce(sum(a.xp), 0) into today_xp from live_answers a
    where a.user_id = auth.uid() and (a.created_at at time zone 'Indian/Mauritius')::date = today_local();
    if today_xp < 100 then
      res := award_xp(auth.uid(), 10, 'live', s.viz, null, 2, true);
      xp_gain := coalesce((res->>'xp')::int, 0);
      coin_gain := 2;
    end if;
  end if;
  insert into live_answers(session_id, user_id, step, answer, correct, xp, coins)
  values (p_session, auth.uid(), p_step, p_answer, ok, xp_gain, coin_gain);
  return jsonb_build_object('correct', ok, 'xp', xp_gain, 'coins', coin_gain, 'already', false);
end $$;

