insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e062247c-0cc6-55ef-a7e3-9d9e95cba9db', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'A credit customer pays $400 into the business bank account. What happens to the accounting equation?', '["Bank rises and capital rises; both totals increase","Bank rises and liabilities fall; totals unchanged","Bank rises and trade receivables fall; totals unchanged","Trade receivables rise and capital falls by $400"]'::jsonb, 'One asset (bank) goes up and another asset (trade receivables) goes down by the same amount, so totals don''t change.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
