insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a48c85fd-7aee-56cb-a6a4-9813c6412f43', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'Which statement best describes book-keeping?', '["Setting the selling prices of the business''s goods","Checking another firm''s accounts are true and fair","Recording financial transactions in the books","Interpreting the financial statements of a business"]'::jsonb, 'Book-keeping is the detailed day-to-day recording. Accounting goes further: summarising, presenting and interpreting the information.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
