insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('64cd117b-afcd-5a58-a883-7ac3fd994165', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'd4411962-e41d-5055-a836-3c45b7ee20dd', '51780471-a63a-5445-aeff-15f6e054e372', 'What does ''capital'' mean in accounting?', '["The money owed to the business by customers","The total value of all the business''s assets","The cash held in the business bank account","The owner''s investment in the business"]'::jsonb, 'Capital is what the owner has put into the business (plus profits kept in it). The business treats it as owed back to the owner.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
