insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('23982849-5728-5327-add5-05f42a740c5e', '8b591152-0acf-5fe4-a902-2af189f81c0f', '7ad2ea29-cf48-56d2-a3d5-cde90e2c93aa', 'e47ac9b0-3045-5b22-af58-96132f88bbdb', 'What does a statement of account sent by a supplier show?', '["Only the cash sales made to the customer in the period","The profit made by the business during the period","Only the discounts the customer received in the period","Transactions for the period and the balance owed"]'::jsonb, 'It summarises invoices, credit notes and payments so the customer can check the balance they owe.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
