insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('83a1cd6b-66c4-58e9-ac1b-80d24fb349c8', '8b591152-0acf-5fe4-a902-2af189f81c0f', '08bbf3bc-ef3e-530c-ae33-2d912d1383bd', '620884a0-3993-53da-aa32-bce763949081', 'What is a benefit of preparing control accounts?', '["They help locate errors in the sales or purchases ledgers","They replace the trial balance at the end of the year","They remove the need for the business to keep a cash book","They are used to calculate the profit for the year"]'::jsonb, 'If the control account total doesn''t match the ledger balances, the error is narrowed down to that ledger.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
