insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2c3b35bb-e278-5089-a915-f3f8fa6c5d69', '8b591152-0acf-5fe4-a902-2af189f81c0f', '08bbf3bc-ef3e-530c-ae33-2d912d1383bd', '620884a0-3993-53da-aa32-bce763949081', 'Why is a bank reconciliation statement prepared?', '["To explain differences between the cash book and bank statement","To value the inventory held at the end of the financial year","To record all credit sales made during the month in the ledger","To calculate the profit for the year from the bank statement"]'::jsonb, 'It checks both records and finds timing differences and errors, which helps to catch mistakes and fraud.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
