insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ef08db0d-3a04-5200-a7ae-16f4a80ecb85', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Which is capital expenditure?', '["Cost of repairing an old machine","Cost of installing a new machine","Cost of the salespeople''s wages","Cost of fuel for the delivery vans"]'::jsonb, 'Costs of buying a non-current asset and getting it ready to use, including delivery and installation, are capital expenditure. Repairs, fuel and wages are running costs: revenue expenditure.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
