insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('4594c3e7-735e-5434-a88d-c1ccc9f1447a', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Rent of $1 200 is owed at the year end. How is it shown?', '["As an other payable, and added to the rent expense","As a non-current liability, and not added to rent","As an other payable, and deducted from the rent","As an other receivable, and deducted from rent"]'::jsonb, 'Rent owed is an accrued expense: add it to the rent charged in the income statement and show it as an other payable (a current liability).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
