insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f1b0d386-4f84-56d7-a14d-41dfb18599fb', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'At what value should inventory be valued?', '["The higher of cost and net realisable value","The cost of replacing it at the year end","The lower of cost and net realisable value","The selling price the business expects to get"]'::jsonb, 'Prudence says inventory must not be overstated, so it is valued at whichever is lower: cost or net realisable value (selling price less costs to sell).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
