insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('239fb59b-a28f-5789-a0eb-b61bc8cead70', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'How is an increase in the allowance for irrecoverable debts treated?', '["As income in the income statement","As an addition to trade receivables","As a liability in the financial position","As an expense in the income statement"]'::jsonb, 'A bigger allowance for irrecoverable debts reduces profit, so the increase is an expense. The allowance itself is deducted from trade receivables.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
