insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f42e87e5-77ea-5b04-a223-eb56d8c8af68', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'A machine cost $12 000, has a residual value of $2 000 and a useful life of 5 years. What is the annual straight-line depreciation?', '["$2 800","$2 000","$1 600","$2 400"]'::jsonb, 'Straight-line = (cost − residual value) ÷ useful life = ($12 000 − $2 000) ÷ 5 = $2 000 a year.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
