insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('971d7e26-c48f-5950-a294-de9e4514dfb9', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'A machine with a net book value of $3 500 is sold for $3 000. What is the result?', '["A profit on disposal of $500","A loss on disposal of $3 000","A loss on disposal of $500","No profit and no loss at all"]'::jsonb, 'It sold for less than its book value: $3 000 − $3 500 = −$500, a loss on disposal.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
