insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('3d2da977-1b25-5be8-a6ae-4beb2720ad97', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Commission of $300 is owed to the business at the year end. How is it shown?', '["As a non-current asset of the business","As an expense in the income statement","As an other payable (accrued expense)","As an other receivable (accrued income)"]'::jsonb, 'Income earned but not yet received is added to income and shown as an other receivable, a current asset.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
