insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('565e2b15-4a7e-50a2-a29b-6a6347d1eca7', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Why are non-current assets depreciated?', '["To save cash so the asset can be replaced later","To reduce the amount of tax the owner has to pay","To spread their cost over the years they are used","To show the market value of the assets each year"]'::jsonb, 'Depreciation matches the cost of the asset against the revenue it helps earn each year (the accruals/matching concept). It does not set cash aside.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
insert into question_keys (question_id, correct) values ('565e2b15-4a7e-50a2-a29b-6a6347d1eca7', 2) on conflict (question_id) do update set correct = excluded.correct;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d72a9a0d-6f4a-52a2-a28a-ca33e475ff75', '8b591152-0acf-5fe4-a902-2af189f81c0f', '79c7c06e-66cb-5394-ab3e-180441e1f3e2', '23e98317-5b7b-50cf-a297-66766228a072', 'Rent receivable: $4 800 was received in the year, of which $400 is for next year. What is the rent income for this year?', '["$400","$4 800","$5 200","$4 400"]'::jsonb, 'Income received in advance belongs to next year, so this year''s income is $4 800 − $400 = $4 400.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
