insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('95b3c29b-fe3d-50d2-ac8a-a6692071e501', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'af7163b5-1592-5e86-a7c7-5abd6cc7fbcc', 'e2d87dce-ed22-50db-ad06-023648343f53', 'Members owe $200 of subscriptions at the year end. How is this shown in the club''s accounts?', '["Added to subscription income and shown as a current asset","Ignored, because the money has not been received yet","Added to subscription income and shown as a liability","Deducted from subscription income and shown as a liability"]'::jsonb, 'Subscriptions in arrears are income for this year not yet received (accrued income), so they increase income and are a current asset.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
