insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a1b1163c-64e2-54a7-a5d7-56c1db42d340', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'af7163b5-1592-5e86-a7c7-5abd6cc7fbcc', 'e2d87dce-ed22-50db-ad06-023648343f53', 'Profit for the year is $18 000. Partner A gets a salary of $6 000 and interest on capital totals $2 000. How much residual profit is shared in the profit-sharing ratio?', '["$12 000","$26 000","$18 000","$10 000"]'::jsonb, 'Salaries and interest are given out first: $18 000 − $6 000 − $2 000 = $10 000 left to share.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
