insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('8e71fd69-4757-50d5-a589-20a496c98e3f', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'af7163b5-1592-5e86-a7c7-5abd6cc7fbcc', 'e2d87dce-ed22-50db-ad06-023648343f53', 'Incomplete records: at the start of the year a trader''s assets are $40 000 and liabilities $9 000. What is the opening capital?', '["$40 000","$49 000","$31 000","$9 000"]'::jsonb, 'Capital = assets − liabilities = $40 000 − $9 000 = $31 000 (a statement of affairs).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
