insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('b2fd1d4e-324d-5159-a33a-e6c38cef135f', '8b591152-0acf-5fe4-a902-2af189f81c0f', 'af7163b5-1592-5e86-a7c7-5abd6cc7fbcc', 'e2d87dce-ed22-50db-ad06-023648343f53', 'Revenue $60 000, cost of sales $36 000, expenses $14 000. What is the profit for the year?', '["$46 000","$24 000","$10 000","$14 000"]'::jsonb, 'Gross profit = $60 000 − $36 000 = $24 000. Profit for the year = $24 000 − $14 000 = $10 000.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
