insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('93c10de3-9bec-5b28-a318-5832454b2c70', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'Gross profit is $15 000 and cost of sales is $45 000. What is the mark-up?', '["300%","15%","33.3%","25%"]'::jsonb, 'Mark-up = gross profit ÷ cost of sales × 100 = $15 000 ÷ $45 000 × 100 = 33.3%. (25% would be the gross margin.)') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
