insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2253b5fa-9b36-56c2-a457-0be7f81681f6', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'Profit for the year is $12 000 and revenue is $96 000. What is the profit margin?', '["12.5%","80%","1.25%","8%"]'::jsonb, 'Profit margin = profit for the year ÷ revenue × 100 = $12 000 ÷ $96 000 × 100 = 12.5%.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
