insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('b0d61be4-bc9d-576b-a925-55e7622703ba', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'Current assets $24 000 (including inventory $9 000); current liabilities $10 000. What is the liquid (acid test) ratio?', '["3.3 : 1","1.5 : 1","2.4 : 1","0.9 : 1"]'::jsonb, 'Liquid ratio = (current assets − inventory) ÷ current liabilities = ($24 000 − $9 000) ÷ $10 000 = 1.5 : 1.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
