insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('202796b0-30ee-59cb-a3d9-5c20c34e09b0', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'What might a falling current ratio mean?', '["The business has sold its inventory at a large profit","The business may find it harder to pay short-term debts","The business''s profits are rising year after year","The business has bought more premises and machinery"]'::jsonb, 'Fewer current assets per $1 of current liabilities means less cover for debts due soon: a liquidity warning sign.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
