insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('84d8418d-e8e3-5f66-ad45-d959dc8ea43f', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'What does return on capital employed (ROCE) measure?', '["How easily the business can pay short-term debts","How well the business uses its capital to make profit","How quickly the business sells its inventory","How long credit customers take to pay their debts"]'::jsonb, 'ROCE = profit ÷ capital employed × 100. A higher ROCE means each $ invested earns more profit.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
