insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('9f58d1f3-c35d-5843-a514-18a9ddcaee56', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'Which is a limitation of financial statements?', '["They don''t show non-financial factors, like staff skills","They contain too many figures for users to understand","They predict the future results of the business exactly","They are never based on transactions that really happened"]'::jsonb, 'Accounts only record what can be measured in money, so important non-financial factors are left out.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
