insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('520c5319-daaa-53d3-a031-482f148a1ce5', '8b591152-0acf-5fe4-a902-2af189f81c0f', '6ff30615-840a-50de-a460-6c7f1f276aa7', '7b285833-be79-5a63-afbb-b105c4d8ca51', 'Why might a business compare its ratios with the previous year?', '["To calculate the tax the business must pay this year","To value the inventory held at the end of the year","To see whether performance is improving or getting worse","To record the transactions that happened in the year"]'::jsonb, 'Trends over time show whether profitability and liquidity are getting better or worse.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
