insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('cfb20ad2-e96e-5fb9-aaf7-97f887c4a84f', '8b591152-0acf-5fe4-a902-2af189f81c0f', '65da8d2b-1f72-5a8b-a1b6-cb095adcad6a', '6ac9e97d-7d95-59b4-a6bb-75abb3c1887d', 'Which is a sustainability issue a business might report on?', '["Its carbon emissions and waste","Its monthly bank reconciliation","The balance of its petty cash","The totals of its trial balance"]'::jsonb, 'Sustainability reporting covers the business''s impact on the environment and society, not its book-keeping.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
