insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('0cc86af0-27af-592b-ac40-78f157361ba1', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', '904d6d01-c7b4-5c32-aef2-186694669f10', 'What does unlimited liability mean?', '["Owners can only lose the money they invested in the business","The business does not have to pay tax on its profits","Owners may lose personal possessions to pay business debts","The business is not allowed to borrow money from a bank"]'::jsonb, 'With unlimited liability the owner and business are not legally separate, so the owner''s personal possessions can be taken to pay business debts.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
