insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d6b873e6-29e6-5542-aba0-a22c858c06fe', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'd85278ab-73c3-5282-a46a-813d3130834d', 'bbcbecad-5dfa-500e-aebc-dc33eeb82e66', 'What is a disadvantage of email compared with a face-to-face meeting?', '["It is much slower to reach the receiver","No immediate feedback or body language","It is very expensive to send each one","The message cannot be saved or stored"]'::jsonb, 'Email gives no instant feedback or body language, so messages can be misunderstood. It is actually fast, cheap and easy to store.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
