insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('27d9e5a1-1c6e-5786-a478-c7c59de5f48b', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'd85278ab-73c3-5282-a46a-813d3130834d', 'bbcbecad-5dfa-500e-aebc-dc33eeb82e66', 'What does delegation mean?', '["Removing a manager who is not performing well","Recruiting new staff from outside the business","Talking to customers to find out their needs","Giving a subordinate the authority to do a task"]'::jsonb, 'The manager passes authority down but stays responsible for the result. It frees up the manager''s time and can motivate staff.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
