insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('98c2e839-37aa-5da3-a315-8ef01bcf645c', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'd85278ab-73c3-5282-a46a-813d3130834d', 'bbcbecad-5dfa-500e-aebc-dc33eeb82e66', 'Which is a reason for dismissal rather than redundancy?', '["Falling demand for products","Gross misconduct, such as theft","A factory closing","The job no longer being needed"]'::jsonb, 'Dismissal is about the worker''s conduct or performance. Redundancy is when the job itself is no longer needed.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
