insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ee032daf-a65f-55c3-a1ff-1b0c4c20e69a', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'd85278ab-73c3-5282-a46a-813d3130834d', 'bbcbecad-5dfa-500e-aebc-dc33eeb82e66', 'What does internal recruitment mean?', '["Advertising the vacancy in a newspaper or online","Filling a vacancy with someone who already works there","Hiring a skilled worker from a rival competitor","Using a recruitment agency to find a new worker"]'::jsonb, 'Internal recruitment is cheaper and quicker, and the person already knows the business, but it brings in no new ideas.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
