insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('8fb6782f-79f2-5eea-a1e7-c85e7f6924e3', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'd85278ab-73c3-5282-a46a-813d3130834d', 'bbcbecad-5dfa-500e-aebc-dc33eeb82e66', 'Which describes an autocratic leader?', '["Lets staff make most decisions with little interference","Involves staff in decisions before making the final one","Makes decisions alone and expects them to be followed","Gives no instructions and leaves staff to work it out"]'::jsonb, 'Autocratic leaders keep control; democratic leaders involve staff; laissez-faire leaders leave staff to decide.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
