insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7e39ad27-d922-5e3b-a7ff-77217f1b50c8', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', '4a6917c9-553e-55e8-aa82-87402390ef15', '0944761e-b220-5635-aeec-975153efb1f8', 'What does brand loyalty mean?', '["Customers avoid products that advertise","Customers keep buying the same brand","Customers always buy the cheapest one","Customers never shop for things online"]'::jsonb, 'Loyal customers keep coming back, so the business can often charge more and spend less winning them.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
