insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('75b48a40-54d2-5629-ac30-5d9f06ce050f', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'How is the margin of safety calculated?', '["Actual output − break-even output","Total revenue − profit for the year","Selling price − variable cost per unit","Fixed costs ÷ contribution per unit"]'::jsonb, 'Margin of safety = actual output − break-even output. It shows how far sales could fall before the business makes a loss.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
