insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e985df0a-06de-5b56-abea-a3d28bf40692', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'Which is an example of an economy of scale?', '["Low motivation","Poor communication","Bulk-buying discounts","Slow decision-making"]'::jsonb, 'Bulk-buying discounts lower average costs as a firm grows: an economy of scale. Poor communication, low motivation and slow decisions are diseconomies of scale.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
