insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('431c92ac-13b1-5a4a-aa35-5372ee941155', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'What is productivity?', '["The number of workers that the business has","The total revenue earned in a period of time","Output per worker over a period of time","The total output of the business in a year"]'::jsonb, 'Productivity measures efficiency, e.g. 50 units per worker per day. Total output alone ignores how many people produced it.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
