insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('12eae8a7-9b8d-59d3-ad7c-ceff0eb67c64', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'What does just-in-time (JIT) mean?', '["Materials are bought in bulk to get the lowest possible price","Large buffer inventories are kept in case demand suddenly rises","Products are made before any orders arrive from customers","Materials arrive only when needed, so little inventory is held"]'::jsonb, 'JIT saves storage costs and waste, but relies on reliable suppliers.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
