insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('70855be8-572d-539d-acb3-c5ddb8284b18', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'What is batch production?', '["Providing services rather than making physical products","Making identical items continuously on a production line","Making one-off items to each customer''s exact requirements","Making a quantity of one product, then switching to another"]'::jsonb, 'For example, a bakery makes a batch of white bread, then a batch of brown bread.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
