insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('267c4784-2645-511b-a902-5c9e734a29bf', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'What does quality assurance mean?', '["Inspecting only the products once they are finished","Checking quality at every stage of production","Testing products only after customers complain","Leaving quality checks to the customers who buy"]'::jsonb, 'Quality assurance builds quality in throughout; quality control inspects at the end.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
