insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('3df00476-9f54-5df9-ac70-c538d5e85b19', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'Why might a business locate close to its customers?', '["Land near customers is cheaper than land anywhere else","Its product is bulky or perishable and costly to transport","Its raw materials are very heavy and costly to transport","Its workers all live far away from where customers are"]'::jsonb, 'Bulky or perishable products (e.g. bread, drinks) cost a lot to transport, so being near the market keeps costs down.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
