insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('da11c3e9-660d-51c8-a15e-1c4179c45000', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'Which is an example of sustainable production?', '["Using more plastic packaging on products","Dumping waste into rivers to save money","Using renewable energy and recycling waste","Using more energy to make each product"]'::jsonb, 'Sustainable production reduces harm to the environment so future generations can meet their needs.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
