insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('be194840-223f-5500-a3cc-ade3036245c2', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'acfcb10e-2017-5def-aeb1-7d978feeb433', 'b1843aa4-56cf-5714-a55a-5d14084a03e9', 'What is automation in a factory likely to do?', '["Increase the labour costs of the business greatly","Raise productivity but may reduce the number of jobs","Slow production down while workers are trained","Lower the quality of every product that is made"]'::jsonb, 'Machines work faster and more consistently, but some workers may lose their jobs or need retraining.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
