insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('64f044d5-28f9-5677-a1c6-e4fed83c3ea0', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'e645c134-7320-552e-a820-0ae824153b0c', '1a56a715-38e1-551e-a307-65dccf8ba076', 'Why is cash important to a business even if it is profitable?', '["It needs cash to pay suppliers and wages on time","Cash is only needed when profits are falling","Profit and cash are exactly the same thing","Cash is only needed to pay the business''s tax"]'::jsonb, 'Profit can be made on credit sales that haven''t been paid yet. Without cash, the business can''t pay wages and suppliers on time.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
