insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('aa86e303-8544-546c-a72a-d6abe1a97475', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'e645c134-7320-552e-a820-0ae824153b0c', '1a56a715-38e1-551e-a307-65dccf8ba076', 'What does a current ratio of 0.8 : 1 suggest?', '["The business is holding far too much cash in the bank","The business may struggle to pay its short-term debts","The business has very low levels of inventory","The business is very profitable compared with rivals"]'::jsonb, 'Current assets don''t fully cover current liabilities, which is a liquidity problem.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
