insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('24cfa6ec-947b-52e3-a70a-6d5ad0203bc3', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'e645c134-7320-552e-a820-0ae824153b0c', '1a56a715-38e1-551e-a307-65dccf8ba076', 'What is microfinance?', '["Small loans for people who can''t get normal bank loans","A large issue of new shares sold on the stock exchange","A type of insurance that protects small businesses","A government grant given only to very large firms"]'::jsonb, 'Microfinance helps people start small businesses, often in developing countries.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
