insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d36b2b00-3446-508e-a389-805b4301dc89', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'e645c134-7320-552e-a820-0ae824153b0c', '1a56a715-38e1-551e-a307-65dccf8ba076', 'What does crowdfunding mean?', '["Selling non-current assets such as old machinery","Raising small amounts from many people, usually online","Borrowing a large amount from one bank as a loan","Using profit kept in the business from earlier years"]'::jsonb, 'Many people each give a little, often in return for a reward or a share in the business.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
