insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f6727f51-6c2e-5b7d-afdd-284eadca7f77', '1cfd38e6-861e-579b-a83a-d236a693b94a', '558f3894-659e-55a5-a96b-13f911a97931', '7c3203ea-91dd-5bb2-ab4d-40999d911978', 'Which is a factor of production?', '["Money","Enterprise","Profit","Shares"]'::jsonb, 'The four factors of production are land, labour, capital and enterprise. Money is not a factor; it is used to buy them.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
