insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('003d85d3-786b-5132-a2de-55d2355212ed', '1cfd38e6-861e-579b-a83a-d236a693b94a', '558f3894-659e-55a5-a96b-13f911a97931', '7c3203ea-91dd-5bb2-ab4d-40999d911978', 'What does a point inside a PPC show?', '["Unemployed or inefficiently used resources","Output that the economy cannot reach yet","Economic growth in the economy over time","All resources fully and efficiently used"]'::jsonb, 'A point inside the PPC means some resources are unemployed or used inefficiently, so more of both goods could be produced.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
