insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('228334c4-94d4-54ad-a9db-413352434aea', '1cfd38e6-861e-579b-a83a-d236a693b94a', '558f3894-659e-55a5-a96b-13f911a97931', '7c3203ea-91dd-5bb2-ab4d-40999d911978', 'What does moving from one point to another along a PPC show?', '["Economic growth, as more of both goods is produced","Unemployment, as resources are not fully used","Inflation, as the prices of both goods rise","The opportunity cost of producing more of one good"]'::jsonb, 'On the curve all resources are used, so making more of one good means making less of the other.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
