insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('6f2fc4c0-9205-5b59-a424-f53a1cffe152', '1cfd38e6-861e-579b-a83a-d236a693b94a', '558f3894-659e-55a5-a96b-13f911a97931', '7c3203ea-91dd-5bb2-ab4d-40999d911978', 'Which would shift a country''s PPC inwards?', '["Better technology used by firms","More workers joining the labour force","Better education and training for all","A natural disaster destroying factories"]'::jsonb, 'Losing resources reduces what the economy can produce, so the PPC moves inwards.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
