insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2ef6e5f3-9d2e-5582-a2ca-8651dd8b599b', '1cfd38e6-861e-579b-a83a-d236a693b94a', '558f3894-659e-55a5-a96b-13f911a97931', '7c3203ea-91dd-5bb2-ab4d-40999d911978', 'Which of these is a free good?', '["Air","A textbook","Electricity","Tap water"]'::jsonb, 'A free good has no opportunity cost to produce. Tap water and electricity use resources to supply, so they are economic goods.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
