insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ad1ad9d3-8054-5531-a187-900864494ff6', '1cfd38e6-861e-579b-a83a-d236a693b94a', '558f3894-659e-55a5-a96b-13f911a97931', '7c3203ea-91dd-5bb2-ab4d-40999d911978', 'What does occupational mobility of labour mean?', '["Workers'' ability to move house to a different region","The level of wages that workers are paid for their jobs","The age at which workers retire from their jobs","Workers'' ability to change from one type of job to another"]'::jsonb, 'Training and transferable skills increase occupational mobility. Moving to another area is geographical mobility.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
