insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d6cc43cb-955e-5458-ae06-961f999e3c8f', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'a615ef7e-67ea-5066-ae26-9405a496de5d', '7c017a78-cedc-525a-a51e-951868e26c1e', 'What does a rise in the price of a good cause?', '["A shift of the demand curve to the left","An extension (movement along) in demand","A contraction (movement along) in demand","A shift of the demand curve to the right"]'::jsonb, 'A change in the good''s own price causes a movement along the demand curve (a contraction when price rises). Changes in income, tastes or other prices shift the curve.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
