insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ffb9e8b8-3d1c-5ac0-a165-36c64f03fdbc', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'a615ef7e-67ea-5066-ae26-9405a496de5d', '7c017a78-cedc-525a-a51e-951868e26c1e', 'When is supply more price elastic?', '["When there are no spare resources for firms to use","When the good is perishable and cannot be stored","When firms have spare capacity and can store inventory","When production of the good takes a long time to finish"]'::jsonb, 'If firms can quickly raise output or sell from stock, quantity supplied responds strongly to price changes.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
