insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('8d81efcd-0612-58f2-aec4-e870a7f41211', '1cfd38e6-861e-579b-a83a-d236a693b94a', '50693a18-f1ee-5073-a782-088fbee2fa16', 'c69bd4d4-fb70-54be-ab1d-1c0c6c6d7deb', 'How is total cost calculated?', '["Fixed cost + variable cost","Price × quantity sold","Average cost × price","Total revenue − profit"]'::jsonb, 'Total cost = fixed cost + variable cost. Price × quantity is total revenue.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
