insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2d6ccba8-f177-5e6e-afb2-a1835b246933', '1cfd38e6-861e-579b-a83a-d236a693b94a', '50693a18-f1ee-5073-a782-088fbee2fa16', 'c69bd4d4-fb70-54be-ab1d-1c0c6c6d7deb', 'What is a monopoly?', '["A department of the government","A tax on large businesses'' profits","A market with many small firms","A market with a single supplier"]'::jsonb, 'A monopoly is a market with a single supplier, protected by high barriers to entry.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
