insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('4628fd71-5520-5add-a475-d2de238c5be5', '1cfd38e6-861e-579b-a83a-d236a693b94a', '50693a18-f1ee-5073-a782-088fbee2fa16', 'c69bd4d4-fb70-54be-ab1d-1c0c6c6d7deb', 'What does division of labour mean?', '["Workers do every task in production","Workers specialise in particular tasks","Workers share their wages equally","Workers are replaced by machinery"]'::jsonb, 'Division of labour means each worker specialises in one task, which raises output per worker but can make work repetitive.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
