insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('2a5f7b79-0eb8-58fc-ad37-026a4f1f8041', '1cfd38e6-861e-579b-a83a-d236a693b94a', '50693a18-f1ee-5073-a782-088fbee2fa16', 'c69bd4d4-fb70-54be-ab1d-1c0c6c6d7deb', 'Production that uses a lot of machinery compared with workers is called what?', '["Land-intensive","Capital-intensive","Enterprise-intensive","Labour-intensive"]'::jsonb, 'Capital-intensive production relies mainly on machines, e.g. car factories with robots.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
