insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f6b157a2-7ba6-50b6-ac2d-d6ee33024d7d', '1cfd38e6-861e-579b-a83a-d236a693b94a', '50693a18-f1ee-5073-a782-088fbee2fa16', 'c69bd4d4-fb70-54be-ab1d-1c0c6c6d7deb', 'What is a feature of a highly competitive market?', '["Only one seller and no competitors","No choice of products for consumers","High barriers that stop new firms","Many firms and low barriers to entry"]'::jsonb, 'With many firms competing and easy entry, prices are kept down and consumers have choice.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
