insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('30c6af33-0219-526b-a453-91222d6d1d1e', '1cfd38e6-861e-579b-a83a-d236a693b94a', '2a9ebb8e-febc-5964-a5f8-e0e20b5184f3', 'a5e85896-724d-53c6-a046-ee070a5cfc89', 'What is inflation?', '["A rise in the number of people unemployed","A sustained fall in the general price level","A rise in the price of one particular good","A sustained rise in the general price level"]'::jsonb, 'Inflation is a sustained rise in the general price level, usually measured by the consumer prices index (CPI). A rise in one price isn''t inflation.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
