insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('28fa37ef-05df-56d9-aec5-d1e6889242e2', '1cfd38e6-861e-579b-a83a-d236a693b94a', '2a9ebb8e-febc-5964-a5f8-e0e20b5184f3', 'a5e85896-724d-53c6-a046-ee070a5cfc89', 'What is one cost of unemployment to the government?', '["Faster economic growth and higher tax revenue","Lower tax revenue and higher spending on benefits","Higher tax revenue and lower spending on benefits","Lower spending on benefits and on retraining"]'::jsonb, 'Unemployed people pay less income tax and may need benefits, worsening the government''s budget.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
