insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('bee2d85a-5e91-502e-a001-abb49857119f', '1cfd38e6-861e-579b-a83a-d236a693b94a', '2a9ebb8e-febc-5964-a5f8-e0e20b5184f3', 'a5e85896-724d-53c6-a046-ee070a5cfc89', 'Which is a macroeconomic aim of government?', '["Low and stable inflation","Higher unemployment","A larger budget deficit","Higher prices for all goods"]'::jsonb, 'Main aims: economic growth, low unemployment, low and stable inflation, a stable balance of payments and fairer income distribution.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
