insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('83a17499-b108-57a5-a8a3-d5f11a245627', '1cfd38e6-861e-579b-a83a-d236a693b94a', '2a9ebb8e-febc-5964-a5f8-e0e20b5184f3', 'a5e85896-724d-53c6-a046-ee070a5cfc89', 'How is a recession usually defined?', '["A fall in unemployment for two quarters","One month in which the price level rises","Two quarters in a row of falling real GDP","A year in which exports rise faster"]'::jsonb, 'In a recession output falls, so incomes fall and unemployment usually rises.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
