insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('be9bd8d5-632b-5e0e-a68a-4d70ea27001d', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'dc370ce2-6d05-51de-a37c-d53daa029452', 'e650a3fd-9a21-5104-ad28-d0e68f7bfe72', 'What does the Human Development Index (HDI) combine?', '["Income, education and life expectancy","Inflation, unemployment and growth","Exports, imports and the exchange rate","Population, land area and birth rate"]'::jsonb, 'The HDI combines income (GNI per head), education (years of schooling) and health (life expectancy), so it measures living standards more widely than income alone.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
