insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('8fb6e4e2-c78e-5d8b-ae08-3a0a94c72680', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'dc370ce2-6d05-51de-a37c-d53daa029452', 'e650a3fd-9a21-5104-ad28-d0e68f7bfe72', 'Which policy could reduce poverty?', '["Providing free education and training","Cutting the national minimum wage","Reducing benefits for the unemployed","Raising taxes on the lowest earners"]'::jsonb, 'Education and training raise skills and earning power, helping people out of poverty in the long run.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
