insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('749afc47-a50b-5e87-aca1-2b97886e7c7c', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'dc370ce2-6d05-51de-a37c-d53daa029452', 'e650a3fd-9a21-5104-ad28-d0e68f7bfe72', 'What is the optimum population?', '["The population that gives the highest output per head","The population when the birth rate equals the death rate","The largest population that a country could support","The population of the country''s capital city"]'::jsonb, 'Below it there are too few workers to use resources fully; above it output per head falls.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
