insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e52be8c9-0be1-50d4-a3d6-4f1581f3f42e', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'dc370ce2-6d05-51de-a37c-d53daa029452', 'e650a3fd-9a21-5104-ad28-d0e68f7bfe72', 'What does GDP per head ignore when comparing living standards?', '["The size of each country''s total population","How income is shared and the quality of life","The total output produced by each economy","The value of goods and services produced"]'::jsonb, 'An average hides inequality and leaves out things like health, education and pollution.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
