insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('6a34fc47-7745-5282-a76e-436c89d3cbd4', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'dc370ce2-6d05-51de-a37c-d53daa029452', 'e650a3fd-9a21-5104-ad28-d0e68f7bfe72', 'Which indicates a higher standard of living?', '["Lower literacy","Higher life expectancy","Lower income per head","Higher infant mortality"]'::jsonb, 'Longer life expectancy reflects better nutrition, healthcare and living conditions.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
