insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('6467282f-8e8f-569b-addd-1a22713c2313', '1cfd38e6-861e-579b-a83a-d236a693b94a', 'dc370ce2-6d05-51de-a37c-d53daa029452', 'e650a3fd-9a21-5104-ad28-d0e68f7bfe72', 'How may foreign aid help development?', '["By increasing the debt the country owes abroad","By raising tariffs on imports from rich countries","By funding infrastructure, health and education","By reducing the country''s exports of raw materials"]'::jsonb, 'Aid can pay for projects that raise productivity and living standards, though it may come with conditions.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
