insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e88c36a4-9d0e-5fde-afd5-594f1dcba570', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', 'ef7aac40-de5a-593a-a205-c95479ea7594', 'Which is an error-detection method?', '["Checksum","Compression","Encryption","Packet switching"]'::jsonb, 'A checksum is calculated before and after sending; if the two values differ, an error happened. Encryption and compression don''t detect errors.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
