insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('24ff1353-7ecb-57cb-a4eb-e0af64eb3b60', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', 'ef7aac40-de5a-593a-a205-c95479ea7594', 'What does symmetric encryption use?', '["A public key to encrypt, a private key to decrypt","No key, just a scrambling algorithm","The same key to encrypt and to decrypt","A different key for every single packet"]'::jsonb, 'Both sender and receiver need the same secret key, so the key itself must be shared securely.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
