insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d8a6aace-4548-598c-aa5c-a2560e364fb3', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', 'ef7aac40-de5a-593a-a205-c95479ea7594', 'What is a disadvantage of parallel transmission over long distances?', '["The bits can arrive out of step (skew)","It can only send one bit at a time","It can only send data in one direction","It is slower than serial over short distances"]'::jsonb, 'Bits on different wires can arrive at slightly different times, so parallel is only used over short distances.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
