insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('96628430-be93-566c-a431-d98cc2cdf6c8', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', 'ef7aac40-de5a-593a-a205-c95479ea7594', 'Why is data split into packets?', '["Packets must all follow the same route to stay in order","Packets can take different routes, avoiding busy links","Smaller packets use less bandwidth than one large message","Splitting data into packets encrypts it automatically"]'::jsonb, 'Packet switching uses the network efficiently; packets are reordered at the destination.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
