insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('b1c78e0b-5306-5d87-a162-3d416709d7fb', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'What does an assembler do?', '["Manages the order in which programs are run","Translates assembly language into machine code","Translates high-level code one line at a time","Translates the whole high-level program at once"]'::jsonb, 'Assembly language uses mnemonics like LDA and ADD; the assembler turns them into binary machine code.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
