insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('b3d3015c-341b-5eba-a240-088aeadef09e', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'What is an advantage of using an interpreter while developing a program?', '["The finished program runs faster than compiled code","Errors are reported line by line, so debugging is easier","The source code stays hidden from anyone running it","It produces an executable file that runs on its own"]'::jsonb, 'The interpreter stops at the error, so you can fix it and carry on testing straight away.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
