insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('0b734285-5a10-556e-afcd-63ed8435f8bb', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'What is an advantage of a compiler?', '["It translates and runs the code line by line","It stops at each error as soon as it finds it","The program can be edited while it is running","The executable runs without the source code"]'::jsonb, 'Once compiled, the program runs quickly and users never see the source code.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
