insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('522832d6-6fd9-58c8-aaf8-42241075805e', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'When is a low-level language most likely to be used?', '["When direct control of the hardware is needed","When beginners are learning how to program","When the code must be easy for others to read","When the code must run on many types of CPU"]'::jsonb, 'Low-level code works directly with registers and memory, so it is used for things like device drivers.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
