insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('508fcc93-d158-52d2-ab2e-1136f239b74b', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'What is firmware?', '["Software in non-volatile memory that starts the hardware","An application that the user installs, such as a game","A utility that scans the computer for viruses and spyware","Software stored in RAM that is lost when power is off"]'::jsonb, 'Firmware is held in ROM/flash and runs when the computer is switched on to load the operating system.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
insert into question_keys (question_id, correct) values ('508fcc93-d158-52d2-ab2e-1136f239b74b', 0) on conflict (question_id) do update set correct = excluded.correct;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('87d5acc0-175d-5e23-a3e5-24ddb7d2090d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'Which of these is application software?', '["An operating system","A spreadsheet","A disk defragmenter utility","A device driver"]'::jsonb, 'Application software does tasks for the user. The others are system software that help run the computer.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
insert into question_keys (question_id, correct) values ('87d5acc0-175d-5e23-a3e5-24ddb7d2090d', 1) on conflict (question_id) do nothing;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a00892f9-8eb7-5981-a45d-35d9de9d95b2', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', '0ff3576b-79aa-5896-aae9-b89095034ab4', 'How does the processor handle an interrupt?', '["It ignores the interrupt until the program has ended","It stops the current instruction and restarts the program","It finishes the current instruction, then runs an ISR","It asks the user whether to handle the interrupt or not"]'::jsonb, 'The current state is saved, the interrupt service routine (ISR) runs, then the original task continues.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
