insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('dec29f31-3fdd-5735-a280-35209f779f50', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', 'c8e14b32-f069-5fa0-a43a-1dd2a4beff2c', 'What is social engineering?', '["Building social media apps that collect personal data","Writing software that spreads through social media","Manipulating people into giving away confidential data","Designing networks so that people can share files"]'::jsonb, 'It targets people rather than computers, e.g. pretending to be IT support to get a password.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
