insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d12cd487-df02-5cfc-a675-d87f249a376d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '6264350f-f6d4-5ad9-a352-7b4727c680bb', 'b826bfec-fa1e-5d37-afdc-ede2f464ddd0', 'What is a logic error?', '["An error that makes the program crash while running","A missing bracket that stops the code from compiling","A keyword that is misspelled, so the code won''t run","An error that gives wrong results without crashing"]'::jsonb, 'The code runs, but the logic is wrong, e.g. using < instead of <=. Misspelled keywords and missing brackets are syntax errors.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
