insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('773f53c7-a840-5e91-a40b-eea954f7f7c6', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '9a70aada-2c44-5164-a728-3caa3b7bfb35', '0ba84087-f3b6-50f7-a914-0b31625e2c57', 'Why use procedures and functions?', '["They stop errors happening because each one is tested on its own","They let a program use more variables than it otherwise could","They make programs run faster because the code is compiled twice","They avoid repeating code and make programs easier to maintain"]'::jsonb, 'Code is written once, tested once and called whenever needed, which makes programs easier to read and update.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
