insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('394c9eba-76b5-520c-a506-1ee4c6787e27', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '14270a41-7c88-5f81-ae15-86701b7aff46', 'd37cec50-e171-5815-a1b1-e8250d4a2fa1', 'Which is an example of capital as a factor of production?', '["An entrepreneur''s new business idea","A delivery van used by a business","Fish swimming in the sea nearby","Money saved in a bank savings account"]'::jsonb, 'Capital is man-made goods used to produce other goods and services.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
