insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('380eaadf-99ca-5ce2-a697-afe0fc1fde9c', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '14270a41-7c88-5f81-ae15-86701b7aff46', 'd37cec50-e171-5815-a1b1-e8250d4a2fa1', 'What does a PPC that is concave (bowed out) to the origin show?', '["No opportunity cost at all","Increasing opportunity cost","Falling opportunity cost","Constant opportunity cost"]'::jsonb, 'Resources are not equally suited to both goods, so each extra unit costs more of the other.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
