insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('02c13a7d-f655-59f3-a35a-c79d94ebb290', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'What does the Human Development Index combine?', '["Income, education and life expectancy","GDP, inflation and the exchange rate","Unemployment, inflation and growth","Exports, imports and the trade balance"]'::jsonb, 'HDI is a broader measure of development.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
