insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('67677c1c-df6b-5a1c-a95a-690143ccd498', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'What is the natural rate of unemployment?', '["The level of unemployment during a recession","The point where there is no unemployment at all","Unemployment when the labour market is in equilibrium","The level of cyclical unemployment in the economy"]'::jsonb, 'It consists of frictional and structural unemployment.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
