insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('dba43108-fa1e-5cc9-a1a5-ec564b00950e', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '030e5a8c-5d6f-5737-a4f0-b5848bf7b506', 'abd39cf9-4802-532a-a50b-a6a5ca2632fc', 'When does crowding out happen?', '["Exports fall because imports are cheaper than home-produced goods","Government borrowing raises interest rates, cutting private investment","Taxes fall, so the government has less money to spend on services","Consumers save more, so firms have less demand for their products"]'::jsonb, 'Private spending is displaced by public spending.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
