insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('9791ceff-edf4-52db-a4dd-3878a4f70175', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '030e5a8c-5d6f-5737-a4f0-b5848bf7b506', 'abd39cf9-4802-532a-a50b-a6a5ca2632fc', 'What does a time lag in policy mean?', '["The effect happens long after the decision","The policy takes effect immediately","The policy always fails to work","Interest rates cannot be changed"]'::jsonb, 'Lags make it hard to fine-tune the economy.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
