insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7ae507f5-4179-5a8c-ad58-b59b651d35ff', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'ba73d79a-7533-5601-a57e-3fd6b411010f', 'a4d31b37-7982-52bb-a6fe-ccc4786116bd', 'According to purchasing power parity theory, exchange rates adjust to do what?', '["Maximise the value of exports from each country","Equalise the interest rates paid in each country","Remove the tariffs charged by each country","Equalise the prices of identical goods in each country"]'::jsonb, 'In the long run currencies should buy the same basket everywhere.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
