insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('9a89cc71-304f-51a9-a4d4-8bf4d64830ed', '20503b30-2347-51fd-a078-27b8850c6557', '661dad7d-d6d9-56cf-a0eb-62a7efd18a73', 'b7c20e1b-1fb4-5132-a71d-c10157724b1f', 'What is a benefit of high capacity utilisation?', '["Easier to take sudden extra orders","Less pressure and stress on staff","More time for repairs and maintenance","Lower average fixed costs per unit"]'::jsonb, 'Fixed costs are spread over more units.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
