insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f920a275-ba31-5458-a179-80df3f9c380a', '103f700e-8c69-5619-a982-5a2b4a8aeca9', '3abbd874-da40-5f90-abb9-91734dfe3d58', 'e2c5eaed-50a4-5927-a4d7-9ee2ede8c7d6', 'What is an embedded system?', '["An app installed on a smartphone for a specific task","A computer built into a larger device for a specific task","A general-purpose computer that can run many programs","A server in the cloud that runs one specific service"]'::jsonb, 'Examples include washing machines and car engine controllers.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
