insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d2d475ad-7146-5bd2-a92e-86ded8e4131c', '00d139c6-357b-5ca0-ab19-e2369aebe747', '65a56281-9deb-5f5b-ac26-255c32357f12', 'fcb85bae-5281-5f3b-aea6-56dfce64f647', 'BitTorrent is an example of what?', '["A peer-to-peer file-sharing protocol","A routing table used by routers","An email protocol for downloading mail","A circuit-switched network protocol"]'::jsonb, 'Peers share pieces of files with each other.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
